from (values
(357690,39744,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... in den Himmel, als die größte Rakete von allen explodierte!'::text,'starrten'::text,'starrten'::text,'haben gestarrt'::text,'Sie starrten in den Himmel, als die größte Rakete von allen explodierte!'::text),
(357694,39744,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... на небо, коли вибухнула найбільша ракета з усіх!'::text,'дивилися'::text,'подивилися'::text,'подивилися'::text,'Вони дивилися на небо, коли вибухнула найбільша ракета з усіх!'::text),
(357693,39744,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ellos ... el cielo cuando explotó el cohete más grande de todos!'::text,'estaban contemplando'::text,'contemplaron'::text,'han contemplado'::text,'¡Ellos estaban contemplando el cielo cuando explotó el cohete más grande de todos!'::text),
(357692,39744,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... le ciel quand la plus grosse fusée de toutes a explosé !'::text,'contemplaient'::text,'ont contemplé'::text,'ont contemplé'::text,'Ils contemplaient le ciel quand la plus grosse fusée de toutes a explosé !'::text),
(357695,39744,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En büyük roket patladığında onlar gökyüzüne ...!'::text,'bakıyorlardı'::text,'baktılar'::text,'baktılar'::text,'En büyük roket patladığında onlar gökyüzüne bakıyorlardı!'::text),
(357696,39744,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az eget ..., amikor felrobbant az összes közül a legnagyobb rakéta!'::text,'bámulták'::text,'bámulták'::text,'bámulták'::text,'Az eget bámulták, amikor felrobbant az összes közül a legnagyobb rakéta!'::text),
(357699,39745,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... schon seit einer Stunde auf das Feuerwerk, und keiner will, dass es aufhört!'::text,'starren'::text,'starren'::text,'starren'::text,'Sie starren schon seit einer Stunde auf das Feuerwerk, und keiner will, dass es aufhört!'::text),
(357703,39745,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... на феєрверк уже годину, і ніхто не хоче, щоб це закінчилося!'::text,'дивляться'::text,'дивляться'::text,'дивляться'::text,'Вони дивляться на феєрверк уже годину, і ніхто не хоче, щоб це закінчилося!'::text),
(357702,39745,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Hace una hora que ... los fuegos artificiales y nadie quiere que termine!'::text,'contemplan'::text,'están contemplando'::text,'contemplan'::text,'¡Hace una hora que contemplan los fuegos artificiales y nadie quiere que termine!'::text),
(357701,39745,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... le feu d''artifice depuis une heure, et personne ne veut que ça s''arrête !'::text,'contemplent'::text,'contemplent'::text,'contemplent'::text,'Ils contemplent le feu d''artifice depuis une heure, et personne ne veut que ça s''arrête !'::text),
(357704,39745,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar bir saattir havai fişeklere ... ve kimse bitmesini istemiyor!'::text,'bakıyorlar'::text,'bakıyorlar'::text,'bakarlar'::text,'Onlar bir saattir havai fişeklere bakıyorlar ve kimse bitmesini istemiyor!'::text),
(357705,39745,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már egy órája ... a tűzijátékot, és senki sem akarja, hogy vége legyen!'::text,'bámulják'::text,'bámulják'::text,'bámulják'::text,'Már egy órája bámulják a tűzijátékot, és senki sem akarja, hogy vége legyen!'::text),
(357717,39747,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, sie hat mir erzählt, dass sie dieses Jahr schon drei Feuerwerke von diesem Dach aus ...'::text,'angeschaut haben'::text,'angeschaut haben'::text,'angeschaut haben'::text,'Bestie, sie hat mir erzählt, dass sie dieses Jahr schon drei Feuerwerke von diesem Dach aus angeschaut haben.'::text),
(357721,39747,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона сказала мені, що цього року вони ... на три феєрверки з того даху.'::text,'дивилися'::text,'дивилися'::text,'дивилися'::text,'Подруго, вона сказала мені, що цього року вони дивилися на три феєрверки з того даху.'::text),
(357720,39747,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, me dijo que este año ... tres espectáculos de fuegos artificiales desde esa azotea.'::text,'han contemplado'::text,'han estado contemplando'::text,'contemplaron'::text,'Amiga, me dijo que este año han contemplado tres espectáculos de fuegos artificiales desde esa azotea.'::text),
(357719,39747,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma bestie, elle m''a dit qu''ils ... trois feux d''artifice depuis ce toit cette année.'::text,'ont contemplé'::text,'ont contemplé'::text,'ont contemplé'::text,'Ma bestie, elle m''a dit qu''ils ont contemplé trois feux d''artifice depuis ce toit cette année.'::text),
(357722,39747,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bana bu yıl o çatıdan üç havai fişek gösterisi ... söyledi.'::text,'izlediklerini'::text,'izlediklerini'::text,'izlediklerini'::text,'Kanka, bana bu yıl o çatıdan üç havai fişek gösterisi izlediklerini söyledi.'::text),
(357723,39747,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy idén már három tűzijátékot ... végig arról a tetőről.'::text,'néztek'::text,'néztek'::text,'néztek'::text,'Csajszi, azt mondta, hogy idén már három tűzijátékot néztek végig arról a tetőről.'::text),
(357726,39748,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, er hat mir erzählt, dass sie bis zum Ende der Show in den Himmel ..., ohne ein einziges Mal zu blinzeln.'::text,'gestarrt hatten'::text,'gestarrt haben'::text,'starrten'::text,'Mädel, er hat mir erzählt, dass sie bis zum Ende der Show in den Himmel gestarrt hatten, ohne ein einziges Mal zu blinzeln.'::text),
(357730,39748,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він сказав мені, що до кінця шоу вони ... на небо, жодного разу не кліпнувши.'::text,'дивилися'::text,'дивилися'::text,'дивилися'::text,'Подруго, він сказав мені, що до кінця шоу вони дивилися на небо, жодного разу не кліпнувши.'::text),
(357729,39748,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me dijo que para cuando terminó el espectáculo, ... el cielo sin parpadear ni una vez.'::text,'habían contemplado'::text,'han contemplado'::text,'contemplaron'::text,'Tía, me dijo que para cuando terminó el espectáculo, habían contemplado el cielo sin parpadear ni una vez.'::text),
(357728,39748,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il m''a dit qu''au moment où le spectacle s''est terminé, ils ... le ciel sans cligner des yeux une seule fois.'::text,'avaient contemplé'::text,'ont contemplé'::text,'ont contemplé'::text,'Meuf, il m''a dit qu''au moment où le spectacle s''est terminé, ils avaient contemplé le ciel sans cligner des yeux une seule fois.'::text),
(357731,39748,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bana gösteri bittiğinde onların gökyüzüne bir kez bile göz kırpmadan ... söyledi.'::text,'bakmış olduklarını'::text,'baktıklarını'::text,'baktıklarını'::text,'Kızım, bana gösteri bittiğinde onların gökyüzüne bir kez bile göz kırpmadan bakmış olduklarını söyledi.'::text),
(357732,39748,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy mire véget ért a show, egyetlen pislogás nélkül ... az eget.'::text,'bámulták'::text,'bámulták'::text,'bámulták'::text,'Csajszi, azt mondta, hogy mire véget ért a show, egyetlen pislogás nélkül bámulták az eget.'::text),
(357735,39749,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn noch eine Rakete aufsteigt, ... sie sie mit offenem Mund an.'::text,'starren'::text,'würden starren'::text,'starrten'::text,'Wenn noch eine Rakete aufsteigt, starren sie sie mit offenem Mund an.'::text),
(357739,39749,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо злетить ще одна ракета, вони ... на неї з відкритими ротами.'::text,'дивитимуться'::text,'дивилися б'::text,'дивилися'::text,'Якщо злетить ще одна ракета, вони дивитимуться на неї з відкритими ротами.'::text),
(357738,39749,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si sube otro cohete, lo ... con la boca abierta.'::text,'contemplarán'::text,'contemplarían'::text,'contemplaron'::text,'Si sube otro cohete, lo contemplarán con la boca abierta.'::text),
(357737,39749,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si une autre fusée monte, ils la ... bouche bée.'::text,'contempleront'::text,'contempleraient'::text,'contemplaient'::text,'Si une autre fusée monte, ils la contempleront bouche bée.'::text),
(357740,39749,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir roket daha yükselirse, ona ağızları açık ...'::text,'bakacaklar'::text,'bakarlardı'::text,'baktılar'::text,'Bir roket daha yükselirse, ona ağızları açık bakacaklar.'::text),
(357741,39749,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha még egy rakéta felszáll, tátott szájjal ...'::text,'fogják bámulni'::text,'bámulnák'::text,'bámulták'::text,'Ha még egy rakéta felszáll, tátott szájjal fogják bámulni.'::text),
(357744,39750,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn es kein Feuerwerk gäbe, ... sie nicht so lange in den dunklen Himmel.'::text,'starrten'::text,'werden starren'::text,'starren'::text,'Wenn es kein Feuerwerk gäbe, starrten sie nicht so lange in den dunklen Himmel.'::text),
(357748,39750,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби не було феєрверку, вони ... на темне небо так довго.'::text,'не дивилися б'::text,'не дивитимуться'::text,'не дивляться'::text,'Якби не було феєрверку, вони не дивилися б на темне небо так довго.'::text),
(357747,39750,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no hubiera fuegos artificiales, ... el cielo oscuro tanto tiempo.'::text,'no contemplarían'::text,'no contemplarán'::text,'no contemplan'::text,'Si no hubiera fuegos artificiales, no contemplarían el cielo oscuro tanto tiempo.'::text),
(357746,39750,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il n''y avait pas de feu d''artifice, ils ne ... pas le ciel sombre aussi longtemps.'::text,'contempleraient'::text,'contempleront'::text,'contemplent'::text,'S''il n''y avait pas de feu d''artifice, ils ne contempleraient pas le ciel sombre aussi longtemps.'::text),
(357749,39750,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Havai fişek olmasaydı, karanlık gökyüzüne bu kadar uzun süre ...'::text,'bakmazlardı'::text,'bakmayacaklar'::text,'bakmıyorlar'::text,'Havai fişek olmasaydı, karanlık gökyüzüne bu kadar uzun süre bakmazlardı.'::text),
(357750,39750,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem lenne tűzijáték, nem ... ilyen sokáig a sötét eget.'::text,'bámulnák'::text,'fogják bámulni'::text,'bámulják'::text,'Ha nem lenne tűzijáték, nem bámulnák ilyen sokáig a sötét eget.'::text),
(357753,39751,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Feuerwerk ... von den drei Leuten auf dem Dach bestaunt.'::text,'wurde'::text,'bestaunte'::text,'wird'::text,'Das Feuerwerk wurde von den drei Leuten auf dem Dach bestaunt.'::text),
(357757,39751,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'За феєрверком ... троє людей на даху.'::text,'спостерігали'::text,'спостерігали'::text,'спостерігають'::text,'За феєрверком спостерігали троє людей на даху.'::text),
(357756,39751,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los fuegos artificiales ... por las tres personas de la azotea.'::text,'fueron contemplados'::text,'contemplaron'::text,'son contemplados'::text,'Los fuegos artificiales fueron contemplados por las tres personas de la azotea.'::text),
(357755,39751,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le feu d''artifice ... par les trois personnes sur le toit.'::text,'a été contemplé'::text,'a contemplé'::text,'est contemplé'::text,'Le feu d''artifice a été contemplé par les trois personnes sur le toit.'::text),
(357758,39751,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Havai fişekler çatıdaki üç kişi tarafından ...'::text,'izlendi'::text,'izledi'::text,'izleniyor'::text,'Havai fişekler çatıdaki üç kişi tarafından izlendi.'::text),
(357759,39751,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tűzijátékot ... a tetőn álló három ember.'::text,'bámulta'::text,'bámulta'::text,'bámulja'::text,'A tűzijátékot bámulta a tetőn álló három ember.'::text),
(357762,39752,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... in den Himmel, weil das Feuerwerk am Himmel ist.'::text,'starren'::text,'werden angestarrt'::text,'starrend'::text,'Sie starren in den Himmel, weil das Feuerwerk am Himmel ist.'::text),
(357766,39752,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... на небо, бо феєрверк на небі.'::text,'дивляться'::text,'розглядаються'::text,'дивлячись'::text,'Вони дивляться на небо, бо феєрверк на небі.'::text),
(357765,39752,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ellos ... el cielo porque los fuegos artificiales están en el cielo.'::text,'contemplan'::text,'son contemplados'::text,'contemplando'::text,'Ellos contemplan el cielo porque los fuegos artificiales están en el cielo.'::text),
(357764,39752,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... le ciel parce que le feu d''artifice est dans le ciel.'::text,'contemplent'::text,'sont contemplés'::text,'contemplant'::text,'Ils contemplent le ciel parce que le feu d''artifice est dans le ciel.'::text),
(357767,39752,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar gökyüzüne ..., çünkü havai fişekler gökyüzünde.'::text,'bakıyorlar'::text,'bakılıyorlar'::text,'bakarak'::text,'Onlar gökyüzüne bakıyorlar, çünkü havai fişekler gökyüzünde.'::text),
(357768,39752,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az eget ..., mert a tűzijáték az égen van.'::text,'bámulják'::text,'bámulják'::text,'bámulva'::text,'Az eget bámulják, mert a tűzijáték az égen van.'::text),
(357780,39754,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Um Mitternacht ... sie schon drei Stunden in diesen Himmel, und niemand wird je wegschauen!'::text,'starren'::text,'werden starren'::text,'werden starren'::text,'Um Mitternacht starren sie schon drei Stunden in diesen Himmel, und niemand wird je wegschauen!'::text),
(357784,39754,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До півночі вони ... на це небо вже три години, і ніхто ніколи не відведе погляду!'::text,'дивитимуться'::text,'дивитимуться'::text,'дивитимуться'::text,'До півночі вони дивитимуться на це небо вже три години, і ніхто ніколи не відведе погляду!'::text),
(357783,39754,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡A medianoche ya ... este cielo durante tres horas, y nadie apartará nunca la mirada!'::text,'habrán estado contemplando'::text,'estarán contemplando'::text,'contemplarán'::text,'¡A medianoche ya habrán estado contemplando este cielo durante tres horas, y nadie apartará nunca la mirada!'::text),
(357782,39754,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À minuit, ils ... ce ciel pendant trois heures, et personne ne détournera jamais le regard !'::text,'auront contemplé'::text,'contempleront'::text,'contempleront'::text,'À minuit, ils auront contemplé ce ciel pendant trois heures, et personne ne détournera jamais le regard !'::text),
(357785,39754,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gece yarısı olduğunda bu gökyüzüne üç saattir ... ve kimse asla gözünü ayırmayacak!'::text,'bakıyor olacaklar'::text,'bakıyor olacaklar'::text,'bakacaklar'::text,'Gece yarısı olduğunda bu gökyüzüne üç saattir bakıyor olacaklar ve kimse asla gözünü ayırmayacak!'::text),
(357786,39754,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Éjfélkor már három órája ... ezt az eget, és soha senki nem fogja elfordítani a tekintetét!'::text,'bámulják'::text,'fogják bámulni'::text,'fogják bámulni'::text,'Éjfélkor már három órája bámulják ezt az eget, és soha senki nem fogja elfordítani a tekintetét!'::text),
(401799,44645,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vermutlich ... das Subjekt morgen um diese Zeit gerade die Pflanzen mit der Gießkanne.'::text,'gießt'::text,'wird gießen'::text,'gießt'::text,'Vermutlich gießt das Subjekt morgen um diese Zeit gerade die Pflanzen mit der Gießkanne.'::text),
(401803,44645,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Імовірно, завтра в цей час суб''єкт ... рослини з лійки.'::text,'поливатиме'::text,'поллє'::text,'поливає'::text,'Імовірно, завтра в цей час суб''єкт поливатиме рослини з лійки.'::text),
(401802,44645,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Presumiblemente, mañana a esta hora el sujeto ... las plantas con la regadera.'::text,'estará regando'::text,'regará'::text,'riega'::text,'Presumiblemente, mañana a esta hora el sujeto estará regando las plantas con la regadera.'::text),
(401801,44645,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vraisemblablement, demain à la même heure, le sujet ... les plantes avec l''arrosoir.'::text,'sera en train d''arroser'::text,'arrosera'::text,'arrose'::text,'Vraisemblablement, demain à la même heure, le sujet sera en train d''arroser les plantes avec l''arrosoir.'::text),
