(401813,44646,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cidden, o sulama kabını her akşam ... söz veriyor musun?'::text,'kullanacağına'::text,'kullanıyor olacağına'::text,'kullandığına'::text,'Cidden, o sulama kabını her akşam kullanacağına söz veriyor musun?'::text),
(401814,44646,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Komolyan, megígéred, hogy minden este ... azt a locsolókannát?'::text,'használni fogod'::text,'használni fogod'::text,'használod'::text,'Komolyan, megígéred, hogy minden este használni fogod azt a locsolókannát?'::text),
(401817,44647,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ganz ehrlich, wenn ich deine Gießkannen-Skills hätte, ... meine Pflanzen so glücklich aus.'::text,'sähen'::text,'werden aussehen'::text,'sehen'::text,'Ganz ehrlich, wenn ich deine Gießkannen-Skills hätte, sähen meine Pflanzen so glücklich aus.'::text),
(401821,44647,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, якби я мав твої навички з лійкою, мої рослини ... такими щасливими.'::text,'виглядали б'::text,'виглядатимуть'::text,'виглядають'::text,'Не буду брехати, якби я мав твої навички з лійкою, мої рослини виглядали б такими щасливими.'::text),
(401820,44647,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, si tuviera tu habilidad con la regadera, mis plantas ... así de felices.'::text,'se verían'::text,'se verán'::text,'se ven'::text,'No voy a mentir, si tuviera tu habilidad con la regadera, mis plantas se verían así de felices.'::text),
(401819,44647,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, si j''avais ton talent avec l''arrosoir, mes plantes ... aussi heureuses.'::text,'auraient l''air'::text,'auront l''air'::text,'ont l''air'::text,'Je vais pas mentir, si j''avais ton talent avec l''arrosoir, mes plantes auraient l''air aussi heureuses.'::text),
(401822,44647,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, senin sulama kabı becerilerin bende olsaydı, bitkilerim bu kadar mutlu ...'::text,'görünürdü'::text,'görünecek'::text,'görünüyor'::text,'Yalan yok, senin sulama kabı becerilerin bende olsaydı, bitkilerim bu kadar mutlu görünürdü.'::text),
(401823,44647,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem fogok hazudni, ha nekem lenne a te locsolókannás tudásod, a növényeim ilyen boldognak ...'::text,'tűnnének'::text,'fognak tűnni'::text,'tűnnek'::text,'Nem fogok hazudni, ha nekem lenne a te locsolókannás tudásod, a növényeim ilyen boldognak tűnnének.'::text),
(401826,44648,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Balkonpflanzen ... jeden Abend mit einer grünen Gießkanne gegossen.'::text,'werden'::text,'gießen'::text,'gießen'::text,'Die Balkonpflanzen werden jeden Abend mit einer grünen Gießkanne gegossen.'::text),
(401830,44648,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Рослини на балконі ... щовечора із зеленої лійки.'::text,'поливають'::text,'поливають'::text,'поливають'::text,'Рослини на балконі поливають щовечора із зеленої лійки.'::text),
(401829,44648,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las plantas del balcón ... cada noche con una regadera verde.'::text,'se riegan'::text,'riegan'::text,'están regando'::text,'Las plantas del balcón se riegan cada noche con una regadera verde.'::text),
(401828,44648,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les plantes du balcon ... tous les soirs avec un arrosoir vert.'::text,'sont arrosées'::text,'arrosent'::text,'sont en train d''arroser'::text,'Les plantes du balcon sont arrosées tous les soirs avec un arrosoir vert.'::text),
(401831,44648,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Balkondaki bitkiler her akşam yeşil bir sulama kabıyla ...'::text,'sulanır'::text,'sular'::text,'suluyor'::text,'Balkondaki bitkiler her akşam yeşil bir sulama kabıyla sulanır.'::text),
(401832,44648,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az erkélyen lévő növényeket minden este egy zöld locsolókannával ...'::text,'locsolják'::text,'locsolják'::text,'locsolják'::text,'Az erkélyen lévő növényeket minden este egy zöld locsolókannával locsolják.'::text),
(401844,44650,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie sagte, sie ... ihre alte Gießkanne im Jahr davor gekauft.'::text,'habe'::text,'hat'::text,'kauft'::text,'Sie sagte, sie habe ihre alte Gießkanne im Jahr davor gekauft.'::text),
(401848,44650,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона сказала, що ... свою стару лійку роком раніше.'::text,'купила'::text,'купила'::text,'купує'::text,'Вона сказала, що купила свою стару лійку роком раніше.'::text),
(401847,44650,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijo que ... su vieja regadera el año anterior.'::text,'había comprado'::text,'ha comprado'::text,'compra'::text,'Dijo que había comprado su vieja regadera el año anterior.'::text),
(401846,44650,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a dit qu''elle ... son vieil arrosoir l''année d''avant.'::text,'avait acheté'::text,'a acheté'::text,'achète'::text,'Elle a dit qu''elle avait acheté son vieil arrosoir l''année d''avant.'::text),
(401849,44650,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eski sulama kabını bir yıl önce ... söyledi.'::text,'almış olduğunu'::text,'aldığını'::text,'aldığını'::text,'Eski sulama kabını bir yıl önce almış olduğunu söyledi.'::text),
(401850,44650,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta, hogy a régi locsolókannáját az előző évben ...'::text,'vette'::text,'vette'::text,'veszi'::text,'Azt mondta, hogy a régi locsolókannáját az előző évben vette.'::text),
(401853,44651,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr Balkon ... leer, bevor sie eine Gießkanne gekauft hat.'::text,'war früher'::text,'war früher'::text,'war gewöhnt'::text,'Ihr Balkon war früher leer, bevor sie eine Gießkanne gekauft hat.'::text),
(401857,44651,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її балкон ... порожнім, поки вона не купила лійку.'::text,'був раніше'::text,'був раніше'::text,'звик бути'::text,'Її балкон був раніше порожнім, поки вона не купила лійку.'::text),
(401856,44651,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su balcón ... vacío antes de que comprara una regadera.'::text,'solía estar'::text,'solía estar'::text,'estaba acostumbrado a estar'::text,'Su balcón solía estar vacío antes de que comprara una regadera.'::text),
(401855,44651,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son balcon ... vide avant qu''elle achète un arrosoir.'::text,'était'::text,'était'::text,'était habitué à être'::text,'Son balcon était vide avant qu''elle achète un arrosoir.'::text),
(401858,44651,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sulama kabı almadan önce balkonu ...'::text,'eskiden boştu'::text,'boş olurdu'::text,'boş olmaya alışkındı'::text,'Sulama kabı almadan önce balkonu eskiden boştu.'::text),
(401859,44651,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az erkélye ..., mielőtt vett egy locsolókannát.'::text,'régen üres volt'::text,'üres volt'::text,'hozzá volt szokva, hogy üres legyen'::text,'Az erkélye régen üres volt, mielőtt vett egy locsolókannát.'::text),
(401862,44652,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie ... ständig jeden Topf mit dieser Gießkanne, irgendwie iconic.'::text,'gießt'::text,'gießt'::text,'gießt'::text,'Bro, sie gießt ständig jeden Topf mit dieser Gießkanne, irgendwie iconic.'::text),
(401866,44652,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона постійно ... кожен вазон із цієї лійки, трохи культово.'::text,'поливає'::text,'поливати'::text,'поливає'::text,'Бро, вона постійно поливає кожен вазон із цієї лійки, трохи культово.'::text),
(401865,44652,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, no para de ... cada maceta con esa regadera, en plan icónico.'::text,'regar'::text,'regar'::text,'regar'::text,'Bro, no para de regar cada maceta con esa regadera, en plan icónico.'::text),
(401864,44652,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elle arrête pas ... chaque pot avec cet arrosoir, un peu iconique.'::text,'d''arroser'::text,'d''arroser'::text,'d''arroser'::text,'Frérot, elle arrête pas d''arroser chaque pot avec cet arrosoir, un peu iconique.'::text),
(401867,44652,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o sulama kabıyla her saksıyı durmadan ..., biraz ikonik.'::text,'suluyor'::text,'sulamak'::text,'sula'::text,'Kanka, o sulama kabıyla her saksıyı durmadan suluyor, biraz ikonik.'::text),
(401868,44652,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, folyton ... minden cserepet azzal a locsolókannával, elég ikonikus.'::text,'locsolja'::text,'locsolni'::text,'locsol'::text,'Tesó, folyton locsolja minden cserepet azzal a locsolókannával, elég ikonikus.'::text),
(401880,44654,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Gießkanne ... 20 Töpfe pro Füllung, was das Ziel übertrifft.'::text,'bewässert'::text,'bewässert gerade'::text,'hat bewässert'::text,'Ihre Gießkanne bewässert 20 Töpfe pro Füllung, was das Ziel übertrifft.'::text),
(401884,44654,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її лійка ... 20 вазонів за одне наповнення, що перевищує цільовий показник.'::text,'поливає'::text,'поливає'::text,'полила'::text,'Її лійка поливає 20 вазонів за одне наповнення, що перевищує цільовий показник.'::text),
(401883,44654,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su regadera ... 20 macetas por recarga, lo que supera el objetivo.'::text,'riega'::text,'está regando'::text,'ha regado'::text,'Su regadera riega 20 macetas por recarga, lo que supera el objetivo.'::text),
(401882,44654,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son arrosoir ... 20 pots par remplissage, ce qui dépasse l''objectif.'::text,'arrose'::text,'est en train d''arroser'::text,'a arrosé'::text,'Son arrosoir arrose 20 pots par remplissage, ce qui dépasse l''objectif.'::text),
(401885,44654,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sulama kabı her dolumda 20 saksıyı ..., bu da hedefi aşıyor.'::text,'sular'::text,'suluyor'::text,'suladı'::text,'Sulama kabı her dolumda 20 saksıyı sular, bu da hedefi aşıyor.'::text),
(401886,44654,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A locsolókannája töltésenként 20 cserepet ..., ami meghaladja a célt.'::text,'locsol meg'::text,'locsol'::text,'locsolt meg'::text,'A locsolókannája töltésenként 20 cserepet locsol meg, ami meghaladja a célt.'::text),
(401889,44655,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... die Tagetes gegossen, bevor sie die Gießkanne zu den Hängeampeln hob.'::text,'hatte'::text,'hat'::text,'goss'::text,'Sie hatte die Tagetes gegossen, bevor sie die Gießkanne zu den Hängeampeln hob.'::text),
(401893,44655,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... чорнобривці, перш ніж підняла лійку до підвісних кошиків.'::text,'полила'::text,'полила'::text,'поливала'::text,'Вона полила чорнобривці, перш ніж підняла лійку до підвісних кошиків.'::text),
(401892,44655,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... las caléndulas antes de levantar la regadera hacia las cestas colgantes.'::text,'había regado'::text,'ha regado'::text,'estaba regando'::text,'Ella había regado las caléndulas antes de levantar la regadera hacia las cestas colgantes.'::text),
(401891,44655,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... les œillets d''Inde avant de lever l''arrosoir vers les paniers suspendus.'::text,'avait arrosé'::text,'a arrosé'::text,'arrosait'::text,'Elle avait arrosé les œillets d''Inde avant de lever l''arrosoir vers les paniers suspendus.'::text),
(401894,44655,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sulama kabını asma saksılara kaldırmadan önce kadife çiçeklerini ...'::text,'sulamıştı'::text,'suladı'::text,'suluyordu'::text,'Sulama kabını asma saksılara kaldırmadan önce kadife çiçeklerini sulamıştı.'::text),
(401895,44655,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... a büdöskéket, mielőtt felemelte a locsolókannát a függő kosarakhoz.'::text,'meglocsolta'::text,'meglocsolta'::text,'locsolta'::text,'Ő meglocsolta a büdöskéket, mielőtt felemelte a locsolókannát a függő kosarakhoz.'::text),
(352290,39144,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, anscheinend ... sie gerade zum Abschied mit ihren Tüchern, als das Horn der Fähre losging.'::text,'winkten'::text,'winkten'::text,'haben gewinkt'::text,'Mädel, anscheinend winkten sie gerade zum Abschied mit ihren Tüchern, als das Horn der Fähre losging.'::text),
(352294,39144,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, вони ... хустками на прощання, коли пролунав гудок порома.'::text,'махали'::text,'помахали'::text,'помахали'::text,'Подруго, кажуть, вони махали хустками на прощання, коли пролунав гудок порома.'::text),
(352293,39144,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer ... sus pañuelos en señal de despedida cuando sonó la bocina del ferri.'::text,'estaban agitando'::text,'agitaron'::text,'han agitado'::text,'Tía, al parecer estaban agitando sus pañuelos en señal de despedida cuando sonó la bocina del ferri.'::text),
(352292,39144,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment ils ... leurs foulards en signe d''adieu quand la corne du ferry a retenti.'::text,'agitaient'::text,'ont agité'::text,'ont agité'::text,'Meuf, apparemment ils agitaient leurs foulards en signe d''adieu quand la corne du ferry a retenti.'::text),
(352295,39144,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güya feribotun kornası çaldığında onlar veda için eşarplarını ...'::text,'sallıyorlarmış'::text,'sallamışlar'::text,'sallamışlar'::text,'Kızım, güya feribotun kornası çaldığında onlar veda için eşarplarını sallıyorlarmış.'::text),
(352296,39144,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag épp búcsúzóul ... a sáljaikat, amikor megszólalt a komp kürtje.'::text,'lengették'::text,'meglengették'::text,'meglengették'::text,'Csajszi, állítólag épp búcsúzóul lengették a sáljaikat, amikor megszólalt a komp kürtje.'::text),
(352299,39145,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Gruppe am Kai ... schon seit zehn Minuten zum Abschied.'::text,'winkt'::text,'winkt'::text,'winkt'::text,'Die Gruppe am Kai winkt schon seit zehn Minuten zum Abschied.'::text),
(352303,39145,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Група на причалі вже десять хвилин ... на прощання.'::text,'махає'::text,'махає'::text,'махає'::text,'Група на причалі вже десять хвилин махає на прощання.'::text),
(352302,39145,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hace diez minutos que el grupo del muelle ... adiós con la mano.'::text,'dice'::text,'está diciendo'::text,'dice'::text,'Hace diez minutos que el grupo del muelle dice adiós con la mano.'::text),
(352301,39145,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le groupe sur le quai ... signe d''adieu depuis dix minutes.'::text,'fait'::text,'est en train de faire'::text,'fait'::text,'Le groupe sur le quai fait signe d''adieu depuis dix minutes.'::text),
(352304,39145,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rıhtımdaki grup on dakikadır veda için el ...'::text,'sallıyor'::text,'sallıyor'::text,'sallar'::text,'Rıhtımdaki grup on dakikadır veda için el sallıyor.'::text),
(352305,39145,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A rakparton álló csoport már tíz perce ... búcsúzóul.'::text,'integet'::text,'integet'::text,'integet'::text,'A rakparton álló csoport már tíz perce integet búcsúzóul.'::text),
(352308,39146,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Fähre ..., während die Gruppe am Kai zum Abschied winkte.'::text,'legte ab'::text,'legte ab'::text,'hat abgelegt'::text,'Die Fähre legte ab, während die Gruppe am Kai zum Abschied winkte.'::text),
(352312,39146,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пором ..., поки група на причалі махала на прощання.'::text,'відпливав'::text,'відплив'::text,'відплив'::text,'Пором відпливав, поки група на причалі махала на прощання.'::text),
(352311,39146,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El ferri ... mientras el grupo del muelle decía adiós con la mano.'::text,'se estaba alejando'::text,'se alejó'::text,'se ha alejado'::text,'El ferri se estaba alejando mientras el grupo del muelle decía adiós con la mano.'::text),
(352310,39146,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le ferry ... pendant que le groupe sur le quai faisait signe d''adieu.'::text,'s''éloignait'::text,'s''est éloigné'::text,'s''est éloigné'::text,'Le ferry s''éloignait pendant que le groupe sur le quai faisait signe d''adieu.'::text),
(352313,39146,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rıhtımdaki grup veda için el sallarken feribot ...'::text,'uzaklaşıyordu'::text,'uzaklaştı'::text,'uzaklaştı'::text,'Rıhtımdaki grup veda için el sallarken feribot uzaklaşıyordu.'::text),
(352314,39146,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A komp ..., miközben a rakparton álló csoport búcsút intett.'::text,'távolodott'::text,'eltávolodott'::text,'eltávolodott'::text,'A komp távolodott, miközben a rakparton álló csoport búcsút intett.'::text),
(352317,39147,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die ältere Frau hat dieser Fähre schon oft zum Abschied ...'::text,'zugewinkt'::text,'zugewinkt'::text,'zugewinkt'::text,'Die ältere Frau hat dieser Fähre schon oft zum Abschied zugewinkt.'::text),
(352321,39147,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Літня жінка вже багато разів ... цьому порому на прощання.'::text,'махала'::text,'махала'::text,'махала'::text,'Літня жінка вже багато разів махала цьому порому на прощання.'::text),
(352320,39147,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La señora mayor ya ... adiós a este ferri muchas veces.'::text,'ha dicho'::text,'ha estado diciendo'::text,'dijo'::text,'La señora mayor ya ha dicho adiós a este ferri muchas veces.'::text),
(352319,39147,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La dame âgée ... à ce ferry bien des fois.'::text,'a dit adieu'::text,'a dit adieu'::text,'a dit adieu'::text,'La dame âgée a dit adieu à ce ferry bien des fois.'::text),
(352322,39147,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yaşlı kadın bu feribota daha önce defalarca veda için el ...'::text,'salladı'::text,'sallıyor'::text,'salladı'::text,'Yaşlı kadın bu feribota daha önce defalarca veda için el salladı.'::text),
(352323,39147,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az idősebb nő már sokszor ... búcsút ennek a kompnak.'::text,'intett'::text,'intett'::text,'intett'::text,'Az idősebb nő már sokszor intett búcsút ennek a kompnak.'::text),
(352335,39149,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein Abschied ist ein Ritual, ... typischerweise stattfindet, wenn sich eine Gruppe in einem Hafen trennt.'::text,'das'::text,'wer'::text,'wo'::text,'Ein Abschied ist ein Ritual, das typischerweise stattfindet, wenn sich eine Gruppe in einem Hafen trennt.'::text),
(352339,39149,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Прощання — це ритуал, ... зазвичай відбувається, коли група розлучається в порту.'::text,'який'::text,'хто'::text,'де'::text,'Прощання — це ритуал, який зазвичай відбувається, коли група розлучається в порту.'::text),
(352338,39149,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una despedida es un ritual ... suele ocurrir cuando un grupo se separa en un puerto.'::text,'que'::text,'quien'::text,'donde'::text,'Una despedida es un ritual que suele ocurrir cuando un grupo se separa en un puerto.'::text),
(352337,39149,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un adieu est un rituel ... se produit généralement quand un groupe se sépare dans un port.'::text,'qui'::text,'qui'::text,'où'::text,'Un adieu est un rituel qui se produit généralement quand un groupe se sépare dans un port.'::text),
(352340,39149,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Veda, bir grup limanda ayrıldığında genellikle gerçekleşen ... bir ritüeldir.'::text,''::text,NULL::text,NULL::text,'Veda, bir grup limanda ayrıldığında genellikle gerçekleşen bir ritüeldir.'::text),
(352341,39149,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A búcsú olyan rituálé, ... jellemzően akkor zajlik, amikor egy csoport elválik egy kikötőben.'::text,'amely'::text,'aki'::text,'ahol'::text,'A búcsú olyan rituálé, amely jellemzően akkor zajlik, amikor egy csoport elválik egy kikötőben.'::text),
(352344,39150,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie schrie, dass dieser Abschied der schlimmste Moment ihres Lebens ...!'::text,'war'::text,'sein wird'::text,'gerade ist'::text,'Sie schrie, dass dieser Abschied der schlimmste Moment ihres Lebens war!'::text),
(352348,39150,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона кричала, що це прощання ... найгіршою миттю її життя!'::text,'було'::text,'буде'::text,'є'::text,'Вона кричала, що це прощання було найгіршою миттю її життя!'::text),
(352347,39150,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Gritó que esta despedida ... el peor momento de su vida!'::text,'era'::text,'será'::text,'está siendo'::text,'¡Gritó que esta despedida era el peor momento de su vida!'::text),
(352346,39150,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a hurlé que cet adieu ... le pire moment de sa vie !'::text,'était'::text,'sera'::text,'est en train d''être'::text,'Elle a hurlé que cet adieu était le pire moment de sa vie !'::text),
(352349,39150,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu vedanın hayatının en kötü anı ... bağırdı!'::text,'olduğunu'::text,'olacağını'::text,'olmakta olduğunu'::text,'Bu vedanın hayatının en kötü anı olduğunu bağırdı!'::text),
(352350,39150,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt üvöltötte, hogy ez a búcsú ... élete legrosszabb pillanata!'::text,'volt'::text,'lesz'::text,NULL::text,'Azt üvöltötte, hogy ez a búcsú volt élete legrosszabb pillanata!'::text),
(352353,39151,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jeden Sommer ... sie hier zum Abschied, und jeden Sommer war es absolut tragisch!'::text,'winkten'::text,'winkten'::text,'waren gewohnt'::text,'Jeden Sommer winkten sie hier zum Abschied, und jeden Sommer war es absolut tragisch!'::text),
(352357,39151,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Щоліта вони ... тут на прощання, і щоліта це була абсолютна трагедія!'::text,'махали'::text,'махали'::text,'звикли махати'::text,'Щоліта вони махали тут на прощання, і щоліта це була абсолютна трагедія!'::text),
(352356,39151,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Cada verano ... adiós aquí, y cada verano era absolutamente trágico!'::text,'decían'::text,'solían decir'::text,'estaban acostumbrados a decir'::text,'¡Cada verano decían adiós aquí, y cada verano era absolutamente trágico!'::text),
(352355,39151,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque été, ils ... adieu ici, et chaque été c''était absolument tragique !'::text,'disaient'::text,'avaient l''habitude de dire'::text,'étaient habitués à dire'::text,'Chaque été, ils disaient adieu ici, et chaque été c''était absolument tragique !'::text),
(352358,39151,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her yaz burada veda için el ..., ve her yaz bu kesinlikle trajikti!'::text,'sallarlardı'::text,'sallarlardı'::text,'sallamaya alışkındılar'::text,'Her yaz burada veda için el sallarlardı, ve her yaz bu kesinlikle trajikti!'::text),
(352359,39151,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden nyáron itt ... búcsút, és minden nyáron totál tragikus volt!'::text,'intettek'::text,'intettek'::text,'hozzá voltak szokva, hogy intsenek'::text,'Minden nyáron itt intettek búcsút, és minden nyáron totál tragikus volt!'::text),
(352362,39152,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie weigert sich, ein trauriges Lebewohl ..., und wird winken, bis die Fähre verschwindet!'::text,'zu sagen'::text,'sagend'::text,'sagen'::text,'Sie weigert sich, ein trauriges Lebewohl zu sagen, und wird winken, bis die Fähre verschwindet!'::text),
(352366,39152,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона відмовляється ... сумне «прощавай» і махатиме, поки пором не зникне!'::text,'сказати'::text,'кажучи'::text,'сказати'::text,'Вона відмовляється сказати сумне «прощавай» і махатиме, поки пором не зникне!'::text),
(352365,39152,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Se niega a ... un triste adiós y va a despedirse con la mano hasta que el ferri desaparezca!'::text,'decir'::text,'diciendo'::text,'decir'::text,'¡Se niega a decir un triste adiós y va a despedirse con la mano hasta que el ferri desaparezca!'::text),
(352364,39152,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle refuse de ... un triste adieu et fera signe jusqu''à ce que le ferry disparaisse !'::text,'dire'::text,'disant'::text,'dire'::text,'Elle refuse de dire un triste adieu et fera signe jusqu''à ce que le ferry disparaisse !'::text),
(352367,39152,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hüzünlü bir veda ... reddediyor ve feribot kaybolana kadar el sallayacak!'::text,'etmeyi'::text,'ederek'::text,'et'::text,'Hüzünlü bir veda etmeyi reddediyor ve feribot kaybolana kadar el sallayacak!'::text),
(352368,39152,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hajlandó szomorú búcsút ..., és integetni fog, amíg el nem tűnik a komp!'::text,'venni'::text,'véve'::text,'vesz'::text,'Nem hajlandó szomorú búcsút venni, és integetni fog, amíg el nem tűnik a komp!'::text),
(352380,39154,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay also, anscheinend ... sie schon eine halbe Stunde zum Abschied gewinkt, bevor die Fähre endlich ablegte.'::text,'hatten'::text,'haben'::text,'winken'::text,'Okay also, anscheinend hatten sie schon eine halbe Stunde zum Abschied gewinkt, bevor die Fähre endlich ablegte.'::text),
(352384,39154,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, кажуть, вони ... на прощання пів години, перш ніж пором нарешті відплив.'::text,'махали'::text,'махають'::text,'махають'::text,'Коротше, кажуть, вони махали на прощання пів години, перш ніж пором нарешті відплив.'::text),
(352383,39154,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues al parecer ... adiós con la mano media hora antes de que el ferri por fin zarpara.'::text,'habían estado diciendo'::text,'han estado diciendo'::text,'están diciendo'::text,'Vale, pues al parecer habían estado diciendo adiós con la mano media hora antes de que el ferri por fin zarpara.'::text),
(352382,39154,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon alors, apparemment ils ... signe d''adieu pendant une demi-heure avant que le ferry parte enfin.'::text,'avaient fait'::text,'ont fait'::text,'font'::text,'Bon alors, apparemment ils avaient fait signe d''adieu pendant une demi-heure avant que le ferry parte enfin.'::text),
(352385,39154,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neyse, güya feribot sonunda kalkmadan önce yarım saat boyunca veda için el ...'::text,'sallıyorlarmış'::text,'sallıyorlar'::text,'sallıyorlar'::text,'Neyse, güya feribot sonunda kalkmadan önce yarım saat boyunca veda için el sallıyorlarmış.'::text),
(352386,39154,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval, állítólag már fél órája ... búcsút, mielőtt a komp végre elindult.'::text,'integettek'::text,'integetnek'::text,'integetnek'::text,'Szóval, állítólag már fél órája integettek búcsút, mielőtt a komp végre elindult.'::text),
(402420,44714,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Unkraut hatte echt lange Wurzeln, ...?'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Das Unkraut hatte echt lange Wurzeln, oder?'::text),
(402424,44714,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Той бур''ян мав дуже довге коріння, ...?'::text,'правда?'::text,'правда?'::text,'правда?'::text,'Той бур''ян мав дуже довге коріння, правда?'::text),
(402423,44714,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esa mala hierba tenía raíces muy largas, ¿...?'::text,'verdad?'::text,'verdad?'::text,'verdad?'::text,'Esa mala hierba tenía raíces muy largas, ¿verdad?'::text),
(402422,44714,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cette mauvaise herbe avait des racines super longues, ... ?'::text,'non ?'::text,'non ?'::text,'non ?'::text,'Cette mauvaise herbe avait des racines super longues, non ?'::text),
(402425,44714,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O yabani otun gerçekten uzun kökleri vardı, ...?'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'O yabani otun gerçekten uzun kökleri vardı, değil mi?'::text),
(402426,44714,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Annak a gaznak nagyon hosszú gyökerei voltak, ...?'::text,'ugye?'::text,'ugye?'::text,'ugye?'::text,'Annak a gaznak nagyon hosszú gyökerei voltak, ugye?'::text),
(402429,44715,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du hasst Unkraut in deinem Gemüsebeet, und ich ...'::text,'auch'::text,'auch'::text,'auch nicht'::text,'Ehrlich, du hasst Unkraut in deinem Gemüsebeet, und ich auch.'::text),
(402433,44715,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ненавидиш бур''яни на своїй грядці, і я ...'::text,'теж'::text,'теж'::text,'теж ні'::text,'Чесно, ти ненавидиш бур''яни на своїй грядці, і я теж.'::text),
(402432,44715,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En serio, odias las malas hierbas en tu huerto, y yo ...'::text,'también'::text,'también'::text,'tampoco'::text,'En serio, odias las malas hierbas en tu huerto, y yo también.'::text),
(402431,44715,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu détestes les mauvaises herbes dans ton potager, et moi ...'::text,'aussi'::text,'aussi'::text,'non plus'::text,'Franchement, tu détestes les mauvaises herbes dans ton potager, et moi aussi.'::text),
(402434,44715,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, sebze tarhındaki yabani otlardan nefret ediyorsun, ben ...'::text,'de'::text,'de'::text,'de değil'::text,'Açıkçası, sebze tarhındaki yabani otlardan nefret ediyorsun, ben de.'::text),
(402435,44715,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, utálod a gazt a veteményesedben, és én ...'::text,'is'::text,'is'::text,'sem'::text,'Őszintén, utálod a gazt a veteményesedben, és én is.'::text),
(402438,44716,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, bis zum Mittag ... du jedes Unkraut in diesem Gemüsebeet ausgerissen.'::text,'hast'::text,'wirst'::text,'wirst'::text,'Respekt, bis zum Mittag hast du jedes Unkraut in diesem Gemüsebeet ausgerissen.'::text),
(402442,44716,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект, до обіду ти ... кожен бур''ян на цій грядці.'::text,'виполеш'::text,'виполеш'::text,'полотимеш'::text,'Респект, до обіду ти виполеш кожен бур''ян на цій грядці.'::text),
(402441,44716,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respeto, para la hora de comer ... todas las malas hierbas de este huerto.'::text,'habrás arrancado'::text,'arrancarás'::text,'estarás arrancando'::text,'Respeto, para la hora de comer habrás arrancado todas las malas hierbas de este huerto.'::text),
(402440,44716,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect, d''ici midi, tu ... toutes les mauvaises herbes de ce potager.'::text,'auras arraché'::text,'arracheras'::text,'seras en train d''arracher'::text,'Respect, d''ici midi, tu auras arraché toutes les mauvaises herbes de ce potager.'::text),
(402443,44716,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Helal, öğlene kadar bu sebze tarhındaki bütün yabani otları ...'::text,'yolmuş olacaksın'::text,'yolacaksın'::text,'yoluyor olacaksın'::text,'Helal, öğlene kadar bu sebze tarhındaki bütün yabani otları yolmuş olacaksın.'::text),
(402444,44716,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, ebédre ennek a veteményesnek minden gazát ...'::text,'kitéped'::text,'ki fogod tépni'::text,'tépni fogod'::text,'Respekt, ebédre ennek a veteményesnek minden gazát kitéped.'::text),
(402447,44717,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, wenn du das Unkraut nicht ausgerissen hättest, ... das Gemüse keine Chance gehabt.'::text,'hätte'::text,'wird'::text,'hatte'::text,'Ehrlich, wenn du das Unkraut nicht ausgerissen hättest, hätte das Gemüse keine Chance gehabt.'::text),
(402451,44717,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, якби ти не висмикнув той бур''ян, овочі ... шансу.'::text,'не мали б'::text,'не матимуть'::text,'не мали'::text,'Чесно, якби ти не висмикнув той бур''ян, овочі не мали б шансу.'::text),
(402450,44717,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En serio, si no hubieras arrancado esa mala hierba, las verduras ... ninguna oportunidad.'::text,'no habrían tenido'::text,'no tendrán'::text,'no tuvieron'::text,'En serio, si no hubieras arrancado esa mala hierba, las verduras no habrían tenido ninguna oportunidad.'::text),
(402449,44717,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, si tu n''avais pas arraché cette mauvaise herbe, les légumes ... aucune chance.'::text,'n''auraient eu'::text,'n''auront'::text,'n''ont eu'::text,'Franchement, si tu n''avais pas arraché cette mauvaise herbe, les légumes n''auraient eu aucune chance.'::text),
(402452,44717,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, o yabani otu yolmasaydın, sebzelerin hiç şansı ...'::text,'olmazdı'::text,'olmayacak'::text,'olmadı'::text,'Açıkçası, o yabani otu yolmasaydın, sebzelerin hiç şansı olmazdı.'::text),
(402453,44717,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ha nem tépted volna ki azt a gazt, a zöldségeknek ... esélyük.'::text,'nem lett volna'::text,'nem lesz'::text,'nem volt'::text,'Őszintén, ha nem tépted volna ki azt a gazt, a zöldségeknek nem lett volna esélyük.'::text),
(402456,44718,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er behauptete, er ... das Unkraut ohne jede Anstrengung ausgerissen. Eine winzige Pflanze, offensichtlich.'::text,'habe'::text,'reiße'::text,'habe'::text,'Er behauptete, er habe das Unkraut ohne jede Anstrengung ausgerissen. Eine winzige Pflanze, offensichtlich.'::text),
(402460,44718,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він стверджував, що ... бур''ян без жодних зусиль. Крихітна рослинка, звісно.'::text,'висмикнув'::text,'висмикує'::text,'висмикнув'::text,'Він стверджував, що висмикнув бур''ян без жодних зусиль. Крихітна рослинка, звісно.'::text),
(402459,44718,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Afirmó ... la mala hierba sin ningún esfuerzo. Una planta diminuta, obviamente.'::text,'haber arrancado'::text,'arrancando'::text,'arrancó'::text,'Afirmó haber arrancado la mala hierba sin ningún esfuerzo. Una planta diminuta, obviamente.'::text),
(402458,44718,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a prétendu ... la mauvaise herbe sans le moindre effort. Une plante minuscule, évidemment.'::text,'avoir arraché'::text,'arrachant'::text,'a arraché'::text,'Il a prétendu avoir arraché la mauvaise herbe sans le moindre effort. Une plante minuscule, évidemment.'::text),
(402461,44718,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yabani otu hiç zorlanmadan ... iddia etti. Minicik bir bitki, belli ki.'::text,'yolduğunu'::text,'yolmayı'::text,'yoldu'::text,'Yabani otu hiç zorlanmadan yolduğunu iddia etti. Minicik bir bitki, belli ki.'::text),
(402462,44718,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt állította, hogy minden erőfeszítés nélkül ... a gazt. Egy apró növény, nyilván.'::text,'kitépte'::text,'tépi ki'::text,'kitépte'::text,'Azt állította, hogy minden erőfeszítés nélkül kitépte a gazt. Egy apró növény, nyilván.'::text),
(402465,44719,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Unkraut ... sehr tiefe Wurzeln gehabt haben, nach dem Ziehen zu urteilen. Leicht stur.'::text,'muss'::text,'sollte'::text,'kann nicht'::text,'Das Unkraut muss sehr tiefe Wurzeln gehabt haben, nach dem Ziehen zu urteilen. Leicht stur.'::text),
(402469,44719,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Судячи з того, як він тягнув, бур''ян ... дуже глибоке коріння. Трохи впертий.'::text,'напевно, мав'::text,'мав би мати'::text,'не міг мати'::text,'Судячи з того, як він тягнув, бур''ян напевно, мав дуже глибоке коріння. Трохи впертий.'::text),
(402468,44719,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mala hierba ... raíces muy profundas, a juzgar por ese tirón. Un poco terca.'::text,'debió de tener'::text,'debería haber tenido'::text,'no pudo haber tenido'::text,'La mala hierba debió de tener raíces muy profundas, a juzgar por ese tirón. Un poco terca.'::text),
(402467,44719,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mauvaise herbe ... des racines très profondes, vu comment il a tiré. Un peu têtue.'::text,'a dû avoir'::text,'aurait dû avoir'::text,'n''a pas pu avoir'::text,'La mauvaise herbe a dû avoir des racines très profondes, vu comment il a tiré. Un peu têtue.'::text),
(402470,44719,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yabani otun çok derin kökleri ..., o çekişe bakılırsa. Biraz inatçı.'::text,'olmalı'::text,'olmalıydı'::text,'olamaz'::text,'Yabani otun çok derin kökleri olmalı, o çekişe bakılırsa. Biraz inatçı.'::text),
(402471,44719,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gaznak ... nagyon mély gyökerei, ahhoz képest, ahogy húzta. Kicsit makacs.'::text,'biztosan voltak'::text,'kellett volna lenniük'::text,'nem lehettek'::text,'A gaznak biztosan voltak nagyon mély gyökerei, ahhoz képest, ahogy húzta. Kicsit makacs.'::text),
(402474,44720,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nächstes Mal sollte er das Unkraut von einer Maschine ... lassen. Viel weniger dramatisch, offensichtlich.'::text,'ausreißen'::text,'ausreißen'::text,'auszureißen'::text,'Nächstes Mal sollte er das Unkraut von einer Maschine ausreißen lassen. Viel weniger dramatisch, offensichtlich.'::text),
(402478,44720,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Наступного разу хай йому бур''яни ... машина. Набагато менш драматично, звісно.'::text,'висмикне'::text,'висмикне'::text,'висмикне'::text,'Наступного разу хай йому бур''яни висмикне машина. Набагато менш драматично, звісно.'::text),
(402477,44720,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La próxima vez debería mandar ... las malas hierbas con una máquina. Mucho menos dramático, obviamente.'::text,'arrancar'::text,'arrancar'::text,'arrancar'::text,'La próxima vez debería mandar arrancar las malas hierbas con una máquina. Mucho menos dramático, obviamente.'::text),
(402476,44720,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La prochaine fois, il devrait faire ... les mauvaises herbes par une machine. Beaucoup moins dramatique, évidemment.'::text,'arracher'::text,'arracher'::text,'arracher'::text,'La prochaine fois, il devrait faire arracher les mauvaises herbes par une machine. Beaucoup moins dramatique, évidemment.'::text),
(402479,44720,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir dahaki sefere yabani otları bir makineye ... lazım. Çok daha az dramatik, belli ki.'::text,'yoldurması'::text,'yoldurması'::text,'yoldurması'::text,'Bir dahaki sefere yabani otları bir makineye yoldurması lazım. Çok daha az dramatik, belli ki.'::text),
(402480,44720,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Legközelebb egy géppel kéne ... a gazt. Sokkal kevésbé drámai, nyilván.'::text,'kitépetnie'::text,'kitépetnie'::text,'kitépetnie'::text,'Legközelebb egy géppel kéne kitépetnie a gazt. Sokkal kevésbé drámai, nyilván.'::text),
(402483,44721,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wünscht sich, das Unkraut ... nie in seinem Gemüsebeet gewachsen! So ein Albtraum!'::text,'wäre'::text,'wuchs'::text,'würde'::text,'Er wünscht sich, das Unkraut wäre nie in seinem Gemüsebeet gewachsen! So ein Albtraum!'::text),
(402487,44721,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він хотів би, щоб той бур''ян ніколи не ... на його грядці! Який жах!'::text,'виріс'::text,'виростав'::text,'виростав'::text,'Він хотів би, щоб той бур''ян ніколи не виріс на його грядці! Який жах!'::text),
(402486,44721,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Él desearía que esa mala hierba nunca ... en su huerto! ¡Qué pesadilla!'::text,'hubiera crecido'::text,'creciera'::text,'fuera a crecer'::text,'¡Él desearía que esa mala hierba nunca hubiera crecido en su huerto! ¡Qué pesadilla!'::text),
(402485,44721,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il voudrait que cette mauvaise herbe ... dans son potager ! Quel cauchemar !'::text,'n''ait jamais poussé'::text,'ne pousse jamais'::text,'ne pousse jamais'::text,'Il voudrait que cette mauvaise herbe n''ait jamais poussé dans son potager ! Quel cauchemar !'::text),
(402488,44721,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O yabani otun sebze tarhında hiç ... diliyor! Ne kâbus!'::text,'bitmemiş olmasını'::text,'bitmemesini'::text,'bitmeyecek olmasını'::text,'O yabani otun sebze tarhında hiç bitmemiş olmasını diliyor! Ne kâbus!'::text),
(402489,44721,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt kívánja, bárcsak az a gaz soha ... a veteményesében! Micsoda rémálom!'::text,'ne nőtt volna ki'::text,'ne nőne ki'::text,'ne nőne ki'::text,'Azt kívánja, bárcsak az a gaz soha ne nőtt volna ki a veteményesében! Micsoda rémálom!'::text),
(402492,44722,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Unkraut, ... Wurzeln voller Erde waren, hat ihn fast fertiggemacht!'::text,'dessen'::text,'das'::text,'das'::text,'Das Unkraut, dessen Wurzeln voller Erde waren, hat ihn fast fertiggemacht!'::text),
(402496,44722,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бур''ян, ... коріння було повне землі, мало не знищив його!'::text,'чиє'::text,'який'::text,'що'::text,'Бур''ян, чиє коріння було повне землі, мало не знищив його!'::text),
(402495,44722,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La mala hierba, ... raíces estaban llenas de tierra, casi acaba con él!'::text,'cuyas'::text,'que'::text,'que'::text,'¡La mala hierba, cuyas raíces estaban llenas de tierra, casi acaba con él!'::text),
(402494,44722,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mauvaise herbe, ... les racines étaient pleines de terre, a failli l''achever !'::text,'dont'::text,'qui'::text,'que'::text,'La mauvaise herbe, dont les racines étaient pleines de terre, a failli l''achever !'::text),
(402497,44722,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kökleri ... toprakla dolu olan yabani ot neredeyse onu mahvetti!'::text,''::text,NULL::text,NULL::text,'Kökleri toprakla dolu olan yabani ot neredeyse onu mahvetti!'::text),
(402498,44722,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gaz, ... gyökerei tele voltak földdel, majdnem kikészítette!'::text,'amelynek'::text,'amely'::text,'amelyik'::text,'A gaz, amelynek gyökerei tele voltak földdel, majdnem kikészítette!'::text),
(402528,44726,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Gastgeber ... am Tor, als der Reisende ankam, also fühlte er sich willkommen.'::text,'warteten'::text,'warteten'::text,'haben gewartet'::text,'Die Gastgeber warteten am Tor, als der Reisende ankam, also fühlte er sich willkommen.'::text),
(402532,44726,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Господарі ... біля воріт, коли мандрівник прибув, тож він почувався бажаним гостем.'::text,'чекали'::text,'почекали'::text,'почекали'::text,'Господарі чекали біля воріт, коли мандрівник прибув, тож він почувався бажаним гостем.'::text),
(402531,44726,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los anfitriones ... en la puerta cuando llegó el viajero, así que se sintió bienvenido.'::text,'estaban esperando'::text,'esperaron'::text,'han esperado'::text,'Los anfitriones estaban esperando en la puerta cuando llegó el viajero, así que se sintió bienvenido.'::text),
(402530,44726,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les hôtes ... à la porte quand le voyageur est arrivé, alors il s''est senti le bienvenu.'::text,'attendaient'::text,'ont attendu'::text,'ont attendu'::text,'Les hôtes attendaient à la porte quand le voyageur est arrivé, alors il s''est senti le bienvenu.'::text),
(402533,44726,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gezgin geldiğinde ev sahipleri kapıda ..., bu yüzden kendini hoş karşılanmış hissetti.'::text,'bekliyorlardı'::text,'beklediler'::text,'beklediler'::text,'Gezgin geldiğinde ev sahipleri kapıda bekliyorlardı, bu yüzden kendini hoş karşılanmış hissetti.'::text),
(402534,44726,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vendéglátók a kapunál ..., amikor az utazó megérkezett, így szívesen látottnak érezte magát.'::text,'vártak'::text,'vártak'::text,'vártak'::text,'A vendéglátók a kapunál vártak, amikor az utazó megérkezett, így szívesen látottnak érezte magát.'::text),
(402537,44727,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... ihm schon seit zehn Minuten zu! Niemand hat sich je so willkommen gefühlt!'::text,'jubeln'::text,'jubeln'::text,'jubeln'::text,'Sie jubeln ihm schon seit zehn Minuten zu! Niemand hat sich je so willkommen gefühlt!'::text),
(402541,44727,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... йому вже десять хвилин! Ніхто ніколи не почувався таким бажаним!'::text,'аплодують'::text,'аплодують'::text,'аплодують'::text,'Вони аплодують йому вже десять хвилин! Ніхто ніколи не почувався таким бажаним!'::text),
(402540,44727,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Hace diez minutos que lo ...! ¡Nadie se ha sentido nunca tan bienvenido!'::text,'vitorean'::text,'están vitoreando'::text,'vitorean'::text,'¡Hace diez minutos que lo vitorean! ¡Nadie se ha sentido nunca tan bienvenido!'::text),
(402539,44727,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... depuis dix minutes ! Personne ne s''est jamais senti aussi bien accueilli !'::text,'l''acclament'::text,'sont en train de l''acclamer'::text,'l''acclament'::text,'Ils l''acclament depuis dix minutes ! Personne ne s''est jamais senti aussi bien accueilli !'::text),
(402542,44727,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On dakikadır onu ...! Hiç kimse kendini bu kadar hoş karşılanmış hissetmemişti!'::text,'alkışlıyorlar'::text,'alkışlıyorlar'::text,'alkışlarlar'::text,'On dakikadır onu alkışlıyorlar! Hiç kimse kendini bu kadar hoş karşılanmış hissetmemişti!'::text),
(402543,44727,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már tíz perce ... őt! Soha senki nem érezte magát ennyire szívesen látottnak!'::text,'éltetik'::text,'éltetik'::text,'éltetik'::text,'Már tíz perce éltetik őt! Soha senki nem érezte magát ennyire szívesen látottnak!'::text),
(402546,44728,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... gerade durchs Tor, als alle schrien, dass er willkommen sei!'::text,'ging'::text,'ging'::text,'ist gegangen'::text,'Er ging gerade durchs Tor, als alle schrien, dass er willkommen sei!'::text),
(402550,44728,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... через ворота, коли всі закричали, що йому раді!'::text,'проходив'::text,'пройшов'::text,'пройшов'::text,'Він проходив через ворота, коли всі закричали, що йому раді!'::text),
(402549,44728,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Él ... por la puerta cuando todos gritaron que era bienvenido!'::text,'estaba pasando'::text,'pasó'::text,'ha pasado'::text,'¡Él estaba pasando por la puerta cuando todos gritaron que era bienvenido!'::text),
(402548,44728,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... la porte quand tout le monde a crié qu''il était le bienvenu !'::text,'franchissait'::text,'a franchi'::text,'a franchi'::text,'Il franchissait la porte quand tout le monde a crié qu''il était le bienvenu !'::text),
(402551,44728,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Herkes ona hoş geldin diye bağırdığında o kapıdan ...!'::text,'geçiyordu'::text,'geçti'::text,'geçti'::text,'Herkes ona hoş geldin diye bağırdığında o kapıdan geçiyordu!'::text),
(402552,44728,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp ... a kapun, amikor mindenki azt kiabálta, hogy szívesen látják!'::text,'sétált át'::text,'átsétált'::text,'átsétált'::text,'Épp sétált át a kapun, amikor mindenki azt kiabálta, hogy szívesen látják!'::text),
(402555,44729,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, anscheinend ... sie ihm schon drei Kokosnüsse gegeben, also fühlt er sich richtig willkommen.'::text,'haben'::text,'haben'::text,'gaben'::text,'Mädel, anscheinend haben sie ihm schon drei Kokosnüsse gegeben, also fühlt er sich richtig willkommen.'::text),
(402559,44729,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, йому вже ... три кокоси, тож він почувається справді бажаним.'::text,'дали'::text,'давали'::text,'дали'::text,'Подруго, кажуть, йому вже дали три кокоси, тож він почувається справді бажаним.'::text),
(402558,44729,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer ya le ... tres cocos, así que se siente superbienvenido.'::text,'han dado'::text,'han estado dando'::text,'dieron'::text,'Tía, al parecer ya le han dado tres cocos, así que se siente superbienvenido.'::text),
(402557,44729,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment ils lui ... déjà trois noix de coco, du coup il se sent vraiment le bienvenu.'::text,'ont donné'::text,'ont donné'::text,'ont donné'::text,'Meuf, apparemment ils lui ont donné déjà trois noix de coco, du coup il se sent vraiment le bienvenu.'::text),
(402560,44729,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güya ona şimdiden üç hindistancevizi ..., o yüzden kendini gerçekten hoş karşılanmış hissediyor.'::text,'vermişler'::text,'veriyorlarmış'::text,'verdiler'::text,'Kızım, güya ona şimdiden üç hindistancevizi vermişler, o yüzden kendini gerçekten hoş karşılanmış hissediyor.'::text),
(402561,44729,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag már három kókuszt ... neki, szóval tényleg szívesen látottnak érzi magát.'::text,'adtak'::text,'adogattak'::text,'adtak'::text,'Csajszi, állítólag már három kókuszt adtak neki, szóval tényleg szívesen látottnak érzi magát.'::text),
(402564,44730,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Omg, er hat mir erzählt, dass sie schon Blumen bereit ..., bevor er überhaupt ankam. So willkommen!'::text,'hatten'::text,'haben'::text,'haben'::text,'Omg, er hat mir erzählt, dass sie schon Blumen bereit hatten, bevor er überhaupt ankam. So willkommen!'::text),
(402568,44730,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Боже, він сказав мені, що вони ... квіти ще до того, як він узагалі приїхав. Такий бажаний!'::text,'приготували'::text,'приготували'::text,'готують'::text,'Боже, він сказав мені, що вони приготували квіти ще до того, як він узагалі приїхав. Такий бажаний!'::text),
(402567,44730,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dios, me dijo que ... flores preparadas antes de que él siquiera llegara. ¡Súper bienvenido!'::text,'tenían'::text,'tienen'::text,'tienen'::text,'Dios, me dijo que tenían flores preparadas antes de que él siquiera llegara. ¡Súper bienvenido!'::text),
(402566,44730,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Omg, il m''a dit qu''ils ... des fleurs prêtes avant même qu''il arrive. Trop bien accueilli !'::text,'avaient'::text,'ont'::text,'ont'::text,'Omg, il m''a dit qu''ils avaient des fleurs prêtes avant même qu''il arrive. Trop bien accueilli !'::text),
(402569,44730,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aman Tanrım, bana daha o gelmeden çiçekleri ... söyledi. Ne kadar hoş karşılanmış!'::text,'hazırlamış olduklarını'::text,'hazırladıklarını'::text,'hazırladıklarını'::text,'Aman Tanrım, bana daha o gelmeden çiçekleri hazırlamış olduklarını söyledi. Ne kadar hoş karşılanmış!'::text),
(402570,44730,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úristen, azt mondta, hogy már azelőtt ... virágokat, hogy egyáltalán megérkezett. Mennyire szívesen látták!'::text,'előkészítettek'::text,'előkészítettek'::text,'előkészítenek'::text,'Úristen, azt mondta, hogy már azelőtt előkészítettek virágokat, hogy egyáltalán megérkezett. Mennyire szívesen látták!'::text),
(402573,44731,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er eine Woche bleibt, ... die Gastgeber dafür sorgen, dass er sich jeden Tag willkommen fühlt.'::text,'werden'::text,'würden'::text,'haben'::text,'Wenn er eine Woche bleibt, werden die Gastgeber dafür sorgen, dass er sich jeden Tag willkommen fühlt.'::text),
(402577,44731,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він залишиться на тиждень, господарі ... так, щоб він щодня почувався бажаним.'::text,'зроблять'::text,'зробили б'::text,'зробили'::text,'Якщо він залишиться на тиждень, господарі зроблять так, щоб він щодня почувався бажаним.'::text),
(402576,44731,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si se queda una semana, los anfitriones ... que se sienta bienvenido cada día.'::text,'harán'::text,'harían'::text,'hicieron'::text,'Si se queda una semana, los anfitriones harán que se sienta bienvenido cada día.'::text),
(402575,44731,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il reste une semaine, les hôtes le ... se sentir le bienvenu chaque jour.'::text,'feront'::text,'feraient'::text,'ont fait'::text,'S''il reste une semaine, les hôtes le feront se sentir le bienvenu chaque jour.'::text),
(402578,44731,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir hafta kalırsa, ev sahipleri her gün kendini hoş karşılanmış hissetmesini ...'::text,'sağlayacaklar'::text,'sağlarlardı'::text,'sağladılar'::text,'Bir hafta kalırsa, ev sahipleri her gün kendini hoş karşılanmış hissetmesini sağlayacaklar.'::text),
(402579,44731,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy hétig marad, a vendéglátók ..., hogy minden nap szívesen látottnak érezze magát.'::text,'gondoskodni fognak róla'::text,'gondoskodnának róla'::text,'gondoskodtak róla'::text,'Ha egy hétig marad, a vendéglátók gondoskodni fognak róla, hogy minden nap szívesen látottnak érezze magát.'::text),
(402582,44732,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, wenn ich deine Energie hätte, ... ich auch überall so willkommen.'::text,'wäre'::text,'werde'::text,'bin'::text,'Ehrlich, wenn ich deine Energie hätte, wäre ich auch überall so willkommen.'::text),
(402586,44732,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, якби я мав твою енергію, я теж ... всюди таким бажаним.'::text,'був би'::text,'буду'::text,'є'::text,'Чесно, якби я мав твою енергію, я теж був би всюди таким бажаним.'::text),
(402585,44732,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En serio, si tuviera tu energía, yo también ... así de bienvenido en todas partes.'::text,'sería'::text,'seré'::text,'soy'::text,'En serio, si tuviera tu energía, yo también sería así de bienvenido en todas partes.'::text),
(402584,44732,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, si j''avais ton énergie, moi aussi je ... aussi bien accueilli partout.'::text,'serais'::text,'serai'::text,'suis'::text,'Franchement, si j''avais ton énergie, moi aussi je serais aussi bien accueilli partout.'::text),
(402587,44732,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, senin enerjin bende olsaydı, ben de her yerde bu kadar hoş ...'::text,'karşılanırdım'::text,'karşılanacağım'::text,'karşılanıyorum'::text,'Açıkçası, senin enerjin bende olsaydı, ben de her yerde bu kadar hoş karşılanırdım.'::text),
(402588,44732,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ha nekem lenne az energiád, engem is mindenhol ilyen szívesen ...'::text,'látnának'::text,'fognak látni'::text,'látnak'::text,'Őszintén, ha nekem lenne az energiád, engem is mindenhol ilyen szívesen látnának.'::text),
(402591,44733,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Reisende ... mit einer Kette aus weißen Blumen begrüßt und fühlte sich willkommen.'::text,'wurde'::text,'begrüßte'::text,'begrüßte'::text,'Der Reisende wurde mit einer Kette aus weißen Blumen begrüßt und fühlte sich willkommen.'::text),
(402595,44733,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Мандрівника ... ланцюжком із білих квітів, і він почувався бажаним.'::text,'привітали'::text,'привітав'::text,'вітав'::text,'Мандрівника привітали ланцюжком із білих квітів, і він почувався бажаним.'::text),
(402594,44733,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El viajero ... con una guirnalda de flores blancas y se sintió bienvenido.'::text,'fue recibido'::text,'recibió'::text,'estaba recibiendo'::text,'El viajero fue recibido con una guirnalda de flores blancas y se sintió bienvenido.'::text),
(402593,44733,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le voyageur ... avec une guirlande de fleurs blanches et s''est senti le bienvenu.'::text,'a été accueilli'::text,'a accueilli'::text,'accueillait'::text,'Le voyageur a été accueilli avec une guirlande de fleurs blanches et s''est senti le bienvenu.'::text),
(402596,44733,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gezgin beyaz çiçeklerden bir zincirle ... ve kendini hoş karşılanmış hissetti.'::text,'karşılandı'::text,'karşıladı'::text,'karşılıyordu'::text,'Gezgin beyaz çiçeklerden bir zincirle karşılandı ve kendini hoş karşılanmış hissetti.'::text),
(402597,44733,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az utazót fehér virágfüzérrel ..., és szívesen látottnak érezte magát.'::text,'köszöntötték'::text,'köszöntötte'::text,'köszöntötte'::text,'Az utazót fehér virágfüzérrel köszöntötték, és szívesen látottnak érezte magát.'::text),
(402618,44736,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis morgen ... er jeden Gastgeber kennengelernt, bei dem er sich willkommen gefühlt hat.'::text,'hat'::text,'wird'::text,'trifft'::text,'Bis morgen hat er jeden Gastgeber kennengelernt, bei dem er sich willkommen gefühlt hat.'::text),
(402622,44736,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До завтра він ... з кожним господарем, завдяки якому почувався бажаним.'::text,'познайомиться'::text,'знайомитиметься'::text,'знайомиться'::text,'До завтра він познайомиться з кожним господарем, завдяки якому почувався бажаним.'::text),
(402621,44736,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para mañana, ... a todos los anfitriones que lo hicieron sentirse bienvenido.'::text,'habrá conocido'::text,'conocerá'::text,'conoce'::text,'Para mañana, habrá conocido a todos los anfitriones que lo hicieron sentirse bienvenido.'::text),
(402620,44736,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici demain, il ... chaque hôte qui l''a fait se sentir le bienvenu.'::text,'aura rencontré'::text,'rencontrera'::text,'rencontre'::text,'D''ici demain, il aura rencontré chaque hôte qui l''a fait se sentir le bienvenu.'::text),
(402623,44736,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarına kadar kendini hoş karşılanmış hissettiren her ev sahibiyle ...'::text,'tanışmış olacak'::text,'tanışacak'::text,'tanışıyor'::text,'Yarına kadar kendini hoş karşılanmış hissettiren her ev sahibiyle tanışmış olacak.'::text),
(402624,44736,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnapra ... minden vendéglátót, aki miatt szívesen látottnak érezte magát.'::text,'megismeri'::text,'meg fogja ismerni'::text,'megismer'::text,'Holnapra megismeri minden vendéglátót, aki miatt szívesen látottnak érezte magát.'::text),
(390918,43436,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Speichen, ... die Nabe mit der Felge verbinden, sind dünn und aus Metall.'::text,'die'::text,'wer'::text,'wo'::text,'Die Speichen, die die Nabe mit der Felge verbinden, sind dünn und aus Metall.'::text),
(390922,43436,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Спиці, ... з''єднують маточину з ободом, тонкі й металеві.'::text,'які'::text,'хто'::text,'де'::text,'Спиці, які з''єднують маточину з ободом, тонкі й металеві.'::text),
(390921,43436,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los radios ... unen el buje con la llanta son finos y metálicos.'::text,'que'::text,'quien'::text,'donde'::text,'Los radios que unen el buje con la llanta son finos y metálicos.'::text),
(390920,43436,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les rayons ... relient le moyeu à la jante sont fins et en métal.'::text,'qui'::text,'qui'::text,'où'::text,'Les rayons qui relient le moyeu à la jante sont fins et en métal.'::text),
(390923,43436,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Göbeği janta bağlayan ... teller ince ve metaldir.'::text,''::text,NULL::text,NULL::text,'Göbeği janta bağlayan teller ince ve metaldir.'::text),
(390924,43436,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A küllők, ... az agyat a felnivel kötik össze, vékonyak és fémből vannak.'::text,'amelyek'::text,'akik'::text,'ahol'::text,'A küllők, amelyek az agyat a felnivel kötik össze, vékonyak és fémből vannak.'::text),
(361317,40147,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein spannender Nachmittag: Er ... gerade die Nabe eines Rollerrads, als die Kamera nach unten ging.'::text,'zeigte'::text,'zeigte'::text,'hat gezeigt'::text,'Ein spannender Nachmittag: Er zeigte gerade die Nabe eines Rollerrads, als die Kamera nach unten ging.'::text),
(361321,40147,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Захопливий день: він ... маточину колеса самоката, коли камера опустилася.'::text,'показував'::text,'показав'::text,'показав'::text,'Захопливий день: він показував маточину колеса самоката, коли камера опустилася.'::text),
(361320,40147,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una tarde emocionante: ... el buje de una rueda de patinete cuando la cámara bajó.'::text,'estaba enseñando'::text,'enseñó'::text,'ha enseñado'::text,'Una tarde emocionante: estaba enseñando el buje de una rueda de patinete cuando la cámara bajó.'::text),
(361319,40147,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un après-midi palpitant : il ... le moyeu d''une roue de trottinette quand la caméra est descendue.'::text,'montrait'::text,'a montré'::text,'a montré'::text,'Un après-midi palpitant : il montrait le moyeu d''une roue de trottinette quand la caméra est descendue.'::text),
(361322,40147,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Heyecan dolu bir öğleden sonra: kamera aşağı indiğinde o bir scooter tekerleğinin göbeğini ...'::text,'gösteriyordu'::text,'gösterdi'::text,'gösterdi'::text,'Heyecan dolu bir öğleden sonra: kamera aşağı indiğinde o bir scooter tekerleğinin göbeğini gösteriyordu.'::text),
(361323,40147,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Izgalmas délután: épp egy roller kerékagyát ..., amikor a kamera lejjebb ereszkedett.'::text,'mutatta'::text,'megmutatta'::text,'megmutatta'::text,'Izgalmas délután: épp egy roller kerékagyát mutatta, amikor a kamera lejjebb ereszkedett.'::text),
(361326,40148,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eindeutig ein Mann mit vielen Hobbys: Er ... schon den ganzen Tag auf Radnaben.'::text,'starrt'::text,'starrt'::text,'starrt'::text,'Eindeutig ein Mann mit vielen Hobbys: Er starrt schon den ganzen Tag auf Radnaben.'::text),
(361330,40148,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Явно чоловік із багатьма хобі: він ... на маточини коліс увесь день.'::text,'витріщається'::text,'витріщається'::text,'витріщається'::text,'Явно чоловік із багатьма хобі: він витріщається на маточини коліс увесь день.'::text),
(361329,40148,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Claramente un hombre con muchos hobbies: ... bujes de ruedas todo el día.'::text,'ha estado mirando'::text,'está mirando'::text,'mira'::text,'Claramente un hombre con muchos hobbies: ha estado mirando bujes de ruedas todo el día.'::text),
(361328,40148,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Clairement un homme aux mille passions : il ... des moyeux de roue toute la journée.'::text,'fixe'::text,'fixe'::text,'fixe'::text,'Clairement un homme aux mille passions : il fixe des moyeux de roue toute la journée.'::text),
(361331,40148,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki pek çok hobisi olan bir adam: bütün gün tekerlek göbeklerine ...'::text,'bakıp duruyor'::text,'bakıyor'::text,'bakar'::text,'Belli ki pek çok hobisi olan bir adam: bütün gün tekerlek göbeklerine bakıp duruyor.'::text),
(361332,40148,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván egy sokoldalú érdeklődésű ember: egész nap kerékagyakat ...'::text,'bámul'::text,'bámul'::text,'bámul'::text,'Nyilván egy sokoldalú érdeklődésű ember: egész nap kerékagyakat bámul.'::text),
(361335,40149,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... gerade auf die riesige Traktornabe, als er „Nicht dein Ernst!“ schrie.'::text,'starrte'::text,'starrte'::text,'hat gestarrt'::text,'Er starrte gerade auf die riesige Traktornabe, als er „Nicht dein Ernst!“ schrie.'::text),
(361339,40149,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... на величезну маточину трактора, коли закричав: «Не може бути!»'::text,'витріщався'::text,'витріщився'::text,'витріщився'::text,'Він витріщався на величезну маточину трактора, коли закричав: «Не може бути!»'::text),
(361338,40149,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... el enorme buje del tractor cuando gritó «¡No puede ser!»'::text,'estaba mirando fijamente'::text,'miró fijamente'::text,'ha mirado fijamente'::text,'Él estaba mirando fijamente el enorme buje del tractor cuando gritó «¡No puede ser!»'::text),
(361337,40149,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... l''énorme moyeu du tracteur quand il a crié « C''est pas possible ! »'::text,'fixait'::text,'a fixé'::text,'a fixé'::text,'Il fixait l''énorme moyeu du tracteur quand il a crié « C''est pas possible ! »'::text),
(361340,40149,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'“Olamaz!” diye bağırdığında devasa traktör göbeğine ...'::text,'bakıyordu'::text,'baktı'::text,'baktı'::text,'“Olamaz!” diye bağırdığında devasa traktör göbeğine bakıyordu.'::text),
(361341,40149,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp a hatalmas traktor-kerékagyat ..., amikor felkiáltott: „Ez nem lehet!”'::text,'bámulta'::text,'megbámulta'::text,'megbámulta'::text,'Épp a hatalmas traktor-kerékagyat bámulta, amikor felkiáltott: „Ez nem lehet!”'::text),
(361344,40150,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese riesige Traktornabe ... eine Tonne wiegen, und er sieht total geplättet aus!'::text,'muss'::text,'könnte'::text,'kann nicht'::text,'Diese riesige Traktornabe muss eine Tonne wiegen, und er sieht total geplättet aus!'::text),
(361348,40150,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ця гігантська маточина трактора ... важити тонну, а він виглядає абсолютно приголомшеним!'::text,'має'::text,'може'::text,'не може'::text,'Ця гігантська маточина трактора має важити тонну, а він виглядає абсолютно приголомшеним!'::text),
(361347,40150,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ese buje gigante de tractor ... pesar una tonelada, y él parece totalmente alucinado!'::text,'debe de'::text,'podría'::text,'no puede'::text,'¡Ese buje gigante de tractor debe de pesar una tonelada, y él parece totalmente alucinado!'::text),
(361346,40150,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cet énorme moyeu de tracteur ... peser une tonne, et il a l''air complètement sidéré !'::text,'doit'::text,'pourrait'::text,'ne peut pas'::text,'Cet énorme moyeu de tracteur doit peser une tonne, et il a l''air complètement sidéré !'::text),
(361349,40150,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O dev traktör göbeği bir ton ağırlığında ..., ve o da tamamen şaşkın görünüyor!'::text,'olmalı'::text,'olabilir'::text,'olamaz'::text,'O dev traktör göbeği bir ton ağırlığında olmalı, ve o da tamamen şaşkın görünüyor!'::text),
(361350,40150,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az az óriási traktor-kerékagy ... egy tonnát nyom, ő meg teljesen ledöbbent!'::text,'biztosan'::text,'talán'::text,'biztosan nem'::text,'Az az óriási traktor-kerékagy biztosan egy tonnát nyom, ő meg teljesen ledöbbent!'::text),
(361362,40152,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, er hat mir erzählt, die Nabe vom Riesenrad ... größer als seine ganze Werkstatt.'::text,'sei'::text,'ist'::text,'sei gewesen'::text,'Hör zu, er hat mir erzählt, die Nabe vom Riesenrad sei größer als seine ganze Werkstatt.'::text),
(361366,40152,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він сказав мені, що маточина оглядового колеса ... більша за всю його майстерню.'::text,'була'::text,'є'::text,'була'::text,'Слухай, він сказав мені, що маточина оглядового колеса була більша за всю його майстерню.'::text),
(361365,40152,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, me dijo que el buje de la noria ... más grande que todo su taller.'::text,'era'::text,'es'::text,'ha sido'::text,'Escucha, me dijo que el buje de la noria era más grande que todo su taller.'::text),
(361364,40152,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il m''a dit que le moyeu de la grande roue ... plus grand que tout son atelier.'::text,'était'::text,'est'::text,'a été'::text,'Écoute, il m''a dit que le moyeu de la grande roue était plus grand que tout son atelier.'::text),
(361367,40152,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana dönme dolabın göbeğinin bütün atölyesinden daha büyük ... söyledi.'::text,'olduğunu'::text,'olduğunu'::text,'olmuş olduğunu'::text,'Dinle, bana dönme dolabın göbeğinin bütün atölyesinden daha büyük olduğunu söyledi.'::text),
(361368,40152,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy az óriáskerék kerékagya ... nagyobb, mint az egész műhelye.'::text,'volt'::text,NULL::text,'volt'::text,'Figyelj, azt mondta, hogy az óriáskerék kerékagya volt nagyobb, mint az egész műhelye.'::text),
(361371,40153,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, früher ... er sich nicht für Radnaben, aber jetzt ist er irgendwie besessen, echt jetzt.'::text,'interessierte'::text,'würde'::text,'war gewohnt'::text,'Bro, früher interessierte er sich nicht für Radnaben, aber jetzt ist er irgendwie besessen, echt jetzt.'::text),
(361375,40153,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, раніше він ... маточинами коліс, а тепер ними якось одержимий, чесно.'::text,'не цікавився'::text,'не цікавився б'::text,'не звик цікавитися'::text,'Бро, раніше він не цікавився маточинами коліс, а тепер ними якось одержимий, чесно.'::text),
(361374,40153,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, él ... interesarse por los bujes de las ruedas, pero ahora está medio obsesionado, en serio.'::text,'no solía'::text,'no iba a'::text,'no estaba acostumbrado a'::text,'Bro, él no solía interesarse por los bujes de las ruedas, pero ahora está medio obsesionado, en serio.'::text),
(361373,40153,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, avant il ... aux moyeux de roue, mais maintenant il est genre obsédé, sérieux.'::text,'ne s''intéressait pas'::text,'ne s''intéresserait pas'::text,'n''avait pas l''habitude de s''intéresser'::text,'Frérot, avant il ne s''intéressait pas aux moyeux de roue, mais maintenant il est genre obsédé, sérieux.'::text),
(361376,40153,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, eskiden tekerlek göbekleri ..., ama şimdi resmen takıntılı, cidden.'::text,'umurunda olmazdı'::text,'umurunda olmazdı'::text,'umursamaya alışkın değildi'::text,'Kanka, eskiden tekerlek göbekleri umurunda olmazdı, ama şimdi resmen takıntılı, cidden.'::text),
(361377,40153,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, régen ... a kerékagyak, de most kicsit rá van kattanva, komolyan.'::text,'nem érdekelték'::text,'nem érdekelnék'::text,'nem volt hozzászokva'::text,'Tesó, régen nem érdekelték a kerékagyak, de most kicsit rá van kattanva, komolyan.'::text),
(361380,40154,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... ständig die Nabe jedes Rades in der Werkstatt.'::text,'prüft'::text,'zu prüfen'::text,'prüft'::text,'Er prüft ständig die Nabe jedes Rades in der Werkstatt.'::text),
(361384,40154,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він постійно ... маточину кожного колеса в майстерні.'::text,'перевіряє'::text,'перевіряти'::text,'перевіряє'::text,'Він постійно перевіряє маточину кожного колеса в майстерні.'::text),
(361383,40154,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No para de ... el buje de cada rueda del taller.'::text,'revisar'::text,'revisar'::text,'revisar'::text,'No para de revisar el buje de cada rueda del taller.'::text),
(361382,40154,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il n''arrête pas de ... le moyeu de chaque roue de l''atelier.'::text,'vérifier'::text,'vérifier'::text,'vérifier'::text,'Il n''arrête pas de vérifier le moyeu de chaque roue de l''atelier.'::text),
(361385,40154,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Atölyedeki her tekerleğin göbeğini durmadan ...'::text,'kontrol ediyor'::text,'kontrol etmek'::text,'kontrol et'::text,'Atölyedeki her tekerleğin göbeğini durmadan kontrol ediyor.'::text),
(361386,40154,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Folyton ... a műhely összes kerekének agyát.'::text,'ellenőrzi'::text,'ellenőrizni'::text,'ellenőriz'::text,'Folyton ellenőrzi a műhely összes kerekének agyát.'::text),
(361389,40155,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... eines Fahrradrads hält alle Speichen zusammen.'::text,'Die Nabe'::text,'Eine Nabe'::text,'Nabe'::text,'Die Nabe eines Fahrradrads hält alle Speichen zusammen.'::text),
(361393,40155,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... велосипедного колеса тримає всі спиці разом.'::text,'Маточина'::text,'Маточина'::text,'Маточина'::text,'Маточина велосипедного колеса тримає всі спиці разом.'::text),
(361392,40155,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... de una rueda de bicicleta mantiene unidos todos los radios.'::text,'El buje'::text,'Un buje'::text,'Buje'::text,'El buje de una rueda de bicicleta mantiene unidos todos los radios.'::text),
(361391,40155,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... d''une roue de vélo maintient tous les rayons ensemble.'::text,'Le moyeu'::text,'Un moyeu'::text,'Moyeu'::text,'Le moyeu d''une roue de vélo maintient tous les rayons ensemble.'::text),
