(338021,37558,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, aday bu şehirde ..., şimdi resmen ikonik.'::text,'eskiden bir hiçti'::text,'bir hiç olurdu'::text,'bir hiç olmaya alışkındı'::text,'Kanka, aday bu şehirde eskiden bir hiçti, şimdi resmen ikonik.'::text),
(338022,37558,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ebben a városban a jelölt ..., most meg elég ikonikus.'::text,'régen egy senki volt'::text,'egy senki lett volna'::text,'hozzá volt szokva, hogy senki legyen'::text,'Tesó, ebben a városban a jelölt régen egy senki volt, most meg elég ikonikus.'::text),
(392520,43614,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... gerade Kisten auf eine Palette, als der Gabelstapler an den Lagerregalen vorbeifuhr.'::text,'stapelte'::text,'stapelte'::text,'hat gestapelt'::text,'Sie stapelte gerade Kisten auf eine Palette, als der Gabelstapler an den Lagerregalen vorbeifuhr.'::text),
(392524,43614,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... коробки на палету, коли навантажувач проїхав повз складські стелажі.'::text,'складала'::text,'склала'::text,'склала'::text,'Вона складала коробки на палету, коли навантажувач проїхав повз складські стелажі.'::text),
(392523,43614,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... cajas en un palé cuando la carretilla elevadora pasó junto a las estanterías del almacén.'::text,'estaba apilando'::text,'apiló'::text,'ha apilado'::text,'Ella estaba apilando cajas en un palé cuando la carretilla elevadora pasó junto a las estanterías del almacén.'::text),
(392522,43614,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... des cartons sur une palette quand le chariot élévateur est passé devant les rayonnages de stockage.'::text,'empilait'::text,'a empilé'::text,'a empilé'::text,'Elle empilait des cartons sur une palette quand le chariot élévateur est passé devant les rayonnages de stockage.'::text),
(392525,43614,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Forklift depolama raflarının önünden geçtiğinde o bir paletin üzerine kutuları ...'::text,'diziyordu'::text,'dizdi'::text,'dizdi'::text,'Forklift depolama raflarının önünden geçtiğinde o bir paletin üzerine kutuları diziyordu.'::text),
(392526,43614,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp dobozokat ... egy raklapra, amikor a targonca elhaladt a tárolópolcok mellett.'::text,'pakolt'::text,'pakolt'::text,'pakolt'::text,'Épp dobozokat pakolt egy raklapra, amikor a targonca elhaladt a tárolópolcok mellett.'::text),
(392529,43615,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... seit 6 Uhr Paletten zur Einlagerung, gemäß Logistikplan.'::text,'belädt'::text,'belädt'::text,'belädt'::text,'Sie belädt seit 6 Uhr Paletten zur Einlagerung, gemäß Logistikplan.'::text),
(392533,43615,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... палети на зберігання з 6:00, згідно з логістичним планом.'::text,'завантажує'::text,'завантажує'::text,'завантажує'::text,'Вона завантажує палети на зберігання з 6:00, згідно з логістичним планом.'::text),
(392532,43615,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... palés para almacenaje desde las 6:00, según el plan logístico.'::text,'ha estado cargando'::text,'está cargando'::text,'carga'::text,'Ella ha estado cargando palés para almacenaje desde las 6:00, según el plan logístico.'::text),
(392531,43615,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... des palettes pour le stockage depuis 6 h, conformément au plan logistique.'::text,'charge'::text,'charge'::text,'charge'::text,'Elle charge des palettes pour le stockage depuis 6 h, conformément au plan logistique.'::text),
(392534,43615,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lojistik plana göre, saat 6''dan beri depolama için palet ...'::text,'yüklüyor'::text,'yüklüyor'::text,'yükler'::text,'Lojistik plana göre, saat 6''dan beri depolama için palet yüklüyor.'::text),
(392535,43615,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A logisztikai terv szerint reggel 6 óta ... raklapokat tárolásra.'::text,'pakol'::text,'pakol'::text,'pakol'::text,'A logisztikai terv szerint reggel 6 óta pakol raklapokat tárolásra.'::text),
(392538,43616,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sobald die Palette voll war, ... sie sie ins Lager, weil volle Paletten ins Lager kommen.'::text,'brachte'::text,'brachte'::text,'hat gebracht'::text,'Sobald die Palette voll war, brachte sie sie ins Lager, weil volle Paletten ins Lager kommen.'::text),
(392542,43616,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Щойно палета заповнилася, вона ... її на склад, бо повні палети йдуть на склад.'::text,'відвезла'::text,'відвозила'::text,'відвезла'::text,'Щойно палета заповнилася, вона відвезла її на склад, бо повні палети йдуть на склад.'::text),
(392541,43616,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En cuanto el palé estuvo lleno, lo ... al almacén, porque los palés llenos van al almacén.'::text,'llevó'::text,'estaba llevando'::text,'ha llevado'::text,'En cuanto el palé estuvo lleno, lo llevó al almacén, porque los palés llenos van al almacén.'::text),
(392540,43616,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une fois la palette pleine, elle ... en zone de stockage, parce que les palettes pleines vont en zone de stockage.'::text,'l''a emmenée'::text,'l''emmenait'::text,'l''a emmenée'::text,'Une fois la palette pleine, elle l''a emmenée en zone de stockage, parce que les palettes pleines vont en zone de stockage.'::text),
(392543,43616,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Palet dolunca onu depoya ..., çünkü dolu paletler depoya gider.'::text,'götürdü'::text,'götürüyordu'::text,'götürdü'::text,'Palet dolunca onu depoya götürdü, çünkü dolu paletler depoya gider.'::text),
(392544,43616,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amint megtelt a raklap, ... a raktárba, mert a teli raklapok a raktárba mennek.'::text,'bevitte'::text,'vitte'::text,'bevitte'::text,'Amint megtelt a raklap, bevitte a raktárba, mert a teli raklapok a raktárba mennek.'::text),
(392547,43617,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Offensichtlich ... die Mitarbeiterin heute Morgen bisher vier Paletten zur Einlagerung vorbereitet.'::text,'hat'::text,'hat'::text,'bereitete'::text,'Offensichtlich hat die Mitarbeiterin heute Morgen bisher vier Paletten zur Einlagerung vorbereitet.'::text),
(392551,43617,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вочевидь, працівниця цього ранку вже ... чотири палети на зберігання.'::text,'підготувала'::text,'готувала'::text,'підготувала'::text,'Вочевидь, працівниця цього ранку вже підготувала чотири палети на зберігання.'::text),
(392550,43617,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Evidentemente, la trabajadora ... cuatro palés para almacenaje en lo que va de mañana.'::text,'ha preparado'::text,'ha estado preparando'::text,'preparó'::text,'Evidentemente, la trabajadora ha preparado cuatro palés para almacenaje en lo que va de mañana.'::text),
(392549,43617,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Manifestement, l''employée ... quatre palettes pour le stockage depuis ce matin.'::text,'a préparé'::text,'prépare'::text,'a préparé'::text,'Manifestement, l''employée a préparé quatre palettes pour le stockage depuis ce matin.'::text),
(392552,43617,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki işçi bu sabah şimdiye kadar depolama için dört palet ...'::text,'hazırladı'::text,'hazırlıyor'::text,'hazırladı'::text,'Belli ki işçi bu sabah şimdiye kadar depolama için dört palet hazırladı.'::text),
(392553,43617,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilvánvalóan a dolgozó ma reggel eddig négy raklapot ... elő tárolásra.'::text,'készített'::text,'készített'::text,'készített'::text,'Nyilvánvalóan a dolgozó ma reggel eddig négy raklapot készített elő tárolásra.'::text),
(392565,43619,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... du wieder Paletten wie ein Profi ins Lager. Respekt.'::text,'ziehst'::text,'ziehst'::text,'ziehst'::text,'Morgen um diese Zeit ziehst du wieder Paletten wie ein Profi ins Lager. Respekt.'::text),
(392569,43619,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра в цей час ти знову ... палети на склад, як профі. Респект.'::text,'тягтимеш'::text,'потягнеш'::text,'тягнеш'::text,'Завтра в цей час ти знову тягтимеш палети на склад, як профі. Респект.'::text),
(392568,43619,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora ... otra vez palés al almacén como una pro. Respeto.'::text,'estarás arrastrando'::text,'arrastrarás'::text,'arrastras'::text,'Mañana a esta hora estarás arrastrando otra vez palés al almacén como una pro. Respeto.'::text),
(392567,43619,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, tu ... encore des palettes vers le stock comme une pro. Respect.'::text,'seras en train de tirer'::text,'tireras'::text,'tires'::text,'Demain à la même heure, tu seras en train de tirer encore des palettes vers le stock comme une pro. Respect.'::text),
(392570,43619,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte paletleri yine bir profesyonel gibi depoya ...! Helal.'::text,'çekiyor olacaksın'::text,'çekeceksin'::text,'çekiyorsun'::text,'Yarın bu saatte paletleri yine bir profesyonel gibi depoya çekiyor olacaksın! Helal.'::text),
(392571,43619,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor megint profi módjára ... a raklapokat a raktárba. Respekt.'::text,'fogod húzni'::text,'húzod be'::text,'húzod'::text,'Holnap ilyenkor megint profi módjára fogod húzni a raklapokat a raktárba. Respekt.'::text),
(392574,43620,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Schau dir die Palette an! Du ... ehrlich die schnellste Mitarbeiterin im Lager sein.'::text,'musst'::text,'kannst nicht'::text,'solltest'::text,'Schau dir die Palette an! Du musst ehrlich die schnellste Mitarbeiterin im Lager sein.'::text),
(392578,43620,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Глянь на цю палету! Ти ... бути найшвидшою працівницею на складі, чесно.'::text,'маєш'::text,'не можеш'::text,'мала б'::text,'Глянь на цю палету! Ти маєш бути найшвидшою працівницею на складі, чесно.'::text),
(392577,43620,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Mira ese palé! Tú ... ser la trabajadora más rápida del almacén, en serio.'::text,'debes de'::text,'no puedes'::text,'deberías'::text,'¡Mira ese palé! Tú debes de ser la trabajadora más rápida del almacén, en serio.'::text),
(392576,43620,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Regarde cette palette ! Tu ... être l''employée la plus rapide du stock, franchement.'::text,'dois'::text,'ne peux pas'::text,'devrais'::text,'Regarde cette palette ! Tu dois être l''employée la plus rapide du stock, franchement.'::text),
(392579,43620,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu palete bak! Açıkçası depodaki en hızlı çalışan sen ...'::text,'olmalısın'::text,'olamazsın'::text,'olmalısın'::text,'Şu palete bak! Açıkçası depodaki en hızlı çalışan sen olmalısın.'::text),
(392580,43620,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nézd azt a raklapot! Őszintén, te ... a leggyorsabb dolgozó a raktárban.'::text,'biztosan vagy'::text,'nem lehetsz'::text,'kellene lenned'::text,'Nézd azt a raklapot! Őszintén, te biztosan vagy a leggyorsabb dolgozó a raktárban.'::text),
(392583,43621,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieser Gang ... früher leer, aber schau ihn dir jetzt an. Wirklich ein Meisterwerk der Lagerung.'::text,'war'::text,'war'::text,'war gewohnt'::text,'Dieser Gang war früher leer, aber schau ihn dir jetzt an. Wirklich ein Meisterwerk der Lagerung.'::text),
(392587,43621,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цей прохід ... порожнім, але глянь на нього зараз. Справжній шедевр зберігання.'::text,'раніше був'::text,'раніше був'::text,'звик бути'::text,'Цей прохід раніше був порожнім, але глянь на нього зараз. Справжній шедевр зберігання.'::text),
(392586,43621,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Este pasillo ... estar vacío, pero míralo ahora. Una auténtica obra maestra del almacenaje.'::text,'solía'::text,'solía'::text,'estaba acostumbrado a'::text,'Este pasillo solía estar vacío, pero míralo ahora. Una auténtica obra maestra del almacenaje.'::text),
(392585,43621,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cette allée ... vide avant, mais regarde-la maintenant. Un vrai chef-d''œuvre du stockage.'::text,'était'::text,'était'::text,'était habituée à être'::text,'Cette allée était vide avant, mais regarde-la maintenant. Un vrai chef-d''œuvre du stockage.'::text),
(392588,43621,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu koridor eskiden boş ..., ama şimdi bir bak. Gerçekten bir depolama şaheseri.'::text,'olurdu'::text,'olurdu'::text,'olmaya alışkındı'::text,'Bu koridor eskiden boş olurdu, ama şimdi bir bak. Gerçekten bir depolama şaheseri.'::text),
(392589,43621,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a folyosó ..., de nézd meg most. Igazi remekműve a tárolásnak.'::text,'régen üres volt'::text,'régen üres volt'::text,'hozzá volt szokva, hogy üres legyen'::text,'Ez a folyosó régen üres volt, de nézd meg most. Igazi remekműve a tárolásnak.'::text),
(392592,43622,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie genießt es offensichtlich, den ganzen Tag schwere Kisten ins Lager ...'::text,'zu heben'::text,'zu heben'::text,'heben'::text,'Sie genießt es offensichtlich, den ganzen Tag schwere Kisten ins Lager zu heben.'::text),
(392596,43622,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Їй явно подобається ... важкі коробки на склад цілий день.'::text,'піднімати'::text,'піднімати'::text,'піднімати'::text,'Їй явно подобається піднімати важкі коробки на склад цілий день.'::text),
(392595,43622,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Está claro que disfruta ... cajas pesadas al almacén todo el día.'::text,'subiendo'::text,'subir'::text,'subir'::text,'Está claro que disfruta subiendo cajas pesadas al almacén todo el día.'::text),
(392594,43622,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle adore clairement ... des cartons lourds vers le stock toute la journée.'::text,'soulever'::text,'soulever'::text,'soulever'::text,'Elle adore clairement soulever des cartons lourds vers le stock toute la journée.'::text),
(392597,43622,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki bütün gün ağır kutuları depoya ... keyif alıyor.'::text,'kaldırmaktan'::text,'kaldırmaya'::text,'kaldır'::text,'Belli ki bütün gün ağır kutuları depoya kaldırmaktan keyif alıyor.'::text),
(392598,43622,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván élvezi, hogy egész nap nehéz dobozokat ... a raktárba.'::text,'emelget'::text,'emelgetni'::text,'emelget'::text,'Nyilván élvezi, hogy egész nap nehéz dobozokat emelget a raktárba.'::text),
(392601,43623,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die hohen Regale ... immer Lagerplatz für Hunderte von Paletten.'::text,'bieten'::text,'bieten'::text,'haben geboten'::text,'Die hohen Regale bieten immer Lagerplatz für Hunderte von Paletten.'::text),
(392605,43623,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Високі стелажі завжди ... місце для зберігання сотень палет.'::text,'забезпечують'::text,'забезпечують'::text,'забезпечили'::text,'Високі стелажі завжди забезпечують місце для зберігання сотень палет.'::text),
(392604,43623,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las estanterías altas siempre ... almacenaje para cientos de palés.'::text,'ofrecen'::text,'están ofreciendo'::text,'han ofrecido'::text,'Las estanterías altas siempre ofrecen almacenaje para cientos de palés.'::text),
(392603,43623,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les hauts rayonnages ... toujours du stockage pour des centaines de palettes.'::text,'offrent'::text,'offrent'::text,'ont offert'::text,'Les hauts rayonnages offrent toujours du stockage pour des centaines de palettes.'::text),
(392606,43623,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yüksek raflar her zaman yüzlerce palet için depolama alanı ...'::text,'sağlar'::text,'sağlıyor'::text,'sağladı'::text,'Yüksek raflar her zaman yüzlerce palet için depolama alanı sağlar.'::text),
(392607,43623,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A magas polcok mindig több száz raklap tárolását ...'::text,'biztosítják'::text,'biztosítják'::text,'biztosították'::text,'A magas polcok mindig több száz raklap tárolását biztosítják.'::text),
(375870,41764,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... seit Ewigkeiten dieselbe Position, weil sie sich nicht bewegt hat.'::text,'hält'::text,'hielt'::text,'hält'::text,'Sie hält seit Ewigkeiten dieselbe Position, weil sie sich nicht bewegt hat.'::text),
(375874,41764,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... те саме положення цілу вічність, бо вона не рухалася.'::text,'тримає'::text,'тримала'::text,'тримає'::text,'Вона тримає те саме положення цілу вічність, бо вона не рухалася.'::text),
(375873,41764,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... la misma posición desde hace siglos, porque no se ha movido.'::text,'ha estado manteniendo'::text,'mantuvo'::text,'está manteniendo'::text,'Ella ha estado manteniendo la misma posición desde hace siglos, porque no se ha movido.'::text),
(375872,41764,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... la même position depuis une éternité, parce qu''elle n''a pas bougé.'::text,'tient'::text,'a tenu'::text,'tient'::text,'Elle tient la même position depuis une éternité, parce qu''elle n''a pas bougé.'::text),
(375875,41764,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aynı pozisyonda asırlardır ..., çünkü hiç kıpırdamadı.'::text,'duruyor'::text,'durdu'::text,'duruyor'::text,'Aynı pozisyonda asırlardır duruyor, çünkü hiç kıpırdamadı.'::text),
(375876,41764,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Már ezer éve ... ugyanazt a pozíciót, mert meg sem mozdult.'::text,'tartja'::text,'tartotta'::text,'tartja'::text,'Már ezer éve tartja ugyanazt a pozíciót, mert meg sem mozdult.'::text),
(375879,41765,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als der Timer eine Minute erreichte, ... das Subjekt bereits in die Unterarmstütz-Position gewechselt.'::text,'war'::text,'ist'::text,'wechselt'::text,'Als der Timer eine Minute erreichte, war das Subjekt bereits in die Unterarmstütz-Position gewechselt.'::text),
(375883,41765,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли таймер досяг однієї хвилини, суб''єкт уже ... в положення планки на ліктях.'::text,'перейшов'::text,'перейшов'::text,'переходить'::text,'Коли таймер досяг однієї хвилини, суб''єкт уже перейшов в положення планки на ліктях.'::text),
(375882,41765,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando el temporizador llegó a un minuto, el sujeto ya ... a la posición de plancha sobre los codos.'::text,'había pasado'::text,'ha pasado'::text,'pasa'::text,'Cuando el temporizador llegó a un minuto, el sujeto ya había pasado a la posición de plancha sobre los codos.'::text),
(375881,41765,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand le minuteur a atteint une minute, le sujet ... en position de planche sur les coudes.'::text,'était passé'::text,'est passé'::text,'passe'::text,'Quand le minuteur a atteint une minute, le sujet était passé en position de planche sur les coudes.'::text),
(375884,41765,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zamanlayıcı bir dakikaya ulaştığında denek dirsek plank pozisyonuna çoktan ...'::text,'geçmişti'::text,'geçti'::text,'geçiyor'::text,'Zamanlayıcı bir dakikaya ulaştığında denek dirsek plank pozisyonuna çoktan geçmişti.'::text),
(375885,41765,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire az időzítő elérte az egy percet, az alany már ... alkartámasz pozícióba.'::text,'átváltott'::text,'átváltott'::text,'átvált'::text,'Mire az időzítő elérte az egy percet, az alany már átváltott alkartámasz pozícióba.'::text),
(375888,41766,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, morgen um diese Zeit ... du dieselbe Plank-Position wie eine Legende.'::text,'hältst'::text,'hältst'::text,'hältst'::text,'Ehrlich, morgen um diese Zeit hältst du dieselbe Plank-Position wie eine Legende.'::text),
(375892,41766,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, завтра в цей час ти ... те саме положення планки, як легенда.'::text,'триматимеш'::text,'утримаєш'::text,'тримаєш'::text,'Чесно, завтра в цей час ти триматимеш те саме положення планки, як легенда.'::text),
(375891,41766,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En serio, mañana a esta hora ... la misma posición de plancha como una leyenda.'::text,'estarás aguantando'::text,'aguantarás'::text,'aguantas'::text,'En serio, mañana a esta hora estarás aguantando la misma posición de plancha como una leyenda.'::text),
(375890,41766,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, demain à la même heure, tu ... la même position de planche comme une légende.'::text,'seras en train de tenir'::text,'tiendras'::text,'tiens'::text,'Franchement, demain à la même heure, tu seras en train de tenir la même position de planche comme une légende.'::text),
(375893,41766,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, yarın bu saatte aynı plank pozisyonunda bir efsane gibi ...'::text,'duruyor olacaksın'::text,'duracaksın'::text,'duruyorsun'::text,'Açıkçası, yarın bu saatte aynı plank pozisyonunda bir efsane gibi duruyor olacaksın.'::text),
(375894,41766,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, holnap ilyenkor ugyanazt a plank pozíciót ... egy legenda módjára.'::text,'fogod tartani'::text,'tartod majd'::text,'tartod'::text,'Őszintén, holnap ilyenkor ugyanazt a plank pozíciót fogod tartani egy legenda módjára.'::text),
(375897,41767,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ganz ehrlich, ich bin sicher, dass du die Position nächstes Mal volle fünf Minuten ...'::text,'halten wirst'::text,'halten wirst'::text,'hältst'::text,'Ganz ehrlich, ich bin sicher, dass du die Position nächstes Mal volle fünf Minuten halten wirst.'::text),
(375901,41767,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, я впевнений, що наступного разу ти ... цю позицію цілих п''ять хвилин.'::text,'втримаєш'::text,'триматимеш'::text,'тримаєш'::text,'Не буду брехати, я впевнений, що наступного разу ти втримаєш цю позицію цілих п''ять хвилин.'::text),
(375900,41767,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, seguro que la próxima vez ... esa posición cinco minutos enteros.'::text,'aguantarás'::text,'estarás aguantando'::text,'aguantas'::text,'No voy a mentir, seguro que la próxima vez aguantarás esa posición cinco minutos enteros.'::text),
(375899,41767,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, je suis sûr que la prochaine fois tu ... cette position cinq bonnes minutes.'::text,'tiendras'::text,'seras en train de tenir'::text,'tiens'::text,'Je vais pas mentir, je suis sûr que la prochaine fois tu tiendras cette position cinq bonnes minutes.'::text),
(375902,41767,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, eminim bir dahaki sefere o pozisyonu tam beş dakika ...'::text,'koruyacaksın'::text,'koruyor olacaksın'::text,'koruyorsun'::text,'Yalan yok, eminim bir dahaki sefere o pozisyonu tam beş dakika koruyacaksın.'::text),
(375903,41767,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem fogok hazudni, biztos vagyok benne, hogy legközelebb öt teljes percig ... azt a pozíciót.'::text,'megtartod'::text,'tartani fogod'::text,'tartod'::text,'Nem fogok hazudni, biztos vagyok benne, hogy legközelebb öt teljes percig megtartod azt a pozíciót.'::text),
(375915,41769,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie diese Position noch eine Minute ..., ist sie natürlich total entspannt.'::text,'hält'::text,'halten wird'::text,'hielt'::text,'Wenn sie diese Position noch eine Minute hält, ist sie natürlich total entspannt.'::text),
(375919,41769,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вона ... цю позицію ще хвилину, то, звісно, буде зовсім розслабленою.'::text,'протримає'::text,'протримає'::text,'протримала'::text,'Якщо вона протримає цю позицію ще хвилину, то, звісно, буде зовсім розслабленою.'::text),
(375918,41769,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ... esta posición un minuto más, obviamente estará relajadísima.'::text,'aguanta'::text,'aguantará'::text,'aguantó'::text,'Si aguanta esta posición un minuto más, obviamente estará relajadísima.'::text),
(375917,41769,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle ... cette position une minute de plus, elle sera évidemment totalement détendue.'::text,'tient'::text,'tiendra'::text,'tenait'::text,'Si elle tient cette position une minute de plus, elle sera évidemment totalement détendue.'::text),
(375920,41769,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu pozisyonu bir dakika daha ..., elbette tamamen rahatlamış olacak.'::text,'korursa'::text,'koruyacaksa'::text,'korusaydı'::text,'Bu pozisyonu bir dakika daha korursa, elbette tamamen rahatlamış olacak.'::text),
(375921,41769,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha még egy percig ... ezt a pozíciót, nyilván teljesen el lesz lazulva.'::text,'megtartja'::text,'meg fogja tartani'::text,'megtartotta'::text,'Ha még egy percig megtartja ezt a pozíciót, nyilván teljesen el lesz lazulva.'::text),
(375924,41770,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn diese Position auch nur etwas leichter wäre, ... sie offensichtlich nicht so die Zähne zusammen.'::text,'bisse'::text,'wird'::text,'beißt'::text,'Wenn diese Position auch nur etwas leichter wäre, bisse sie offensichtlich nicht so die Zähne zusammen.'::text),
(375928,41770,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби це положення було хоч трохи легшим, вона явно ... так зуби.'::text,'не стискала б'::text,'не стискатиме'::text,'не стискає'::text,'Якби це положення було хоч трохи легшим, вона явно не стискала б так зуби.'::text),
(375927,41770,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si esta posición fuera un poco más fácil, está claro que ... los dientes así.'::text,'no apretaría'::text,'no apretará'::text,'no aprieta'::text,'Si esta posición fuera un poco más fácil, está claro que no apretaría los dientes así.'::text),
(375926,41770,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si cette position était un tant soit peu plus facile, elle ne ... clairement pas les dents comme ça.'::text,'serrerait'::text,'serrera'::text,'serre'::text,'Si cette position était un tant soit peu plus facile, elle ne serrerait clairement pas les dents comme ça.'::text),
