(384839,42760,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, o mektubu bugün gönderirsen birinin bütün haftasını ...'::text,'güzelleştirecek'::text,'güzelleştirirdi'::text,'güzelleştirdi'::text,'Yalan yok, o mektubu bugün gönderirsen birinin bütün haftasını güzelleştirecek.'::text),
