(384843,42761,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie eine E-Mail schicken würde, ... sie in einer Sekunde an. Aber Papier ist natürlich schneller.'::text,'käme'::text,'wird'::text,'kommt'::text,'Wenn sie eine E-Mail schicken würde, käme sie in einer Sekunde an. Aber Papier ist natürlich schneller.'::text),
(384847,42761,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона надіслала імейл, він ... за одну секунду. Але папір, звісно, швидший.'::text,'прийшов би'::text,'прийде'::text,'приходить'::text,'Якби вона надіслала імейл, він прийшов би за одну секунду. Але папір, звісно, швидший.'::text),
(384846,42761,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si enviara un correo, ... en un segundo. Pero, obviamente, el papel es más rápido.'::text,'llegaría'::text,'llegará'::text,'llega'::text,'Si enviara un correo, llegaría en un segundo. Pero, obviamente, el papel es más rápido.'::text),
(384845,42761,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle envoyait un e-mail, il ... en une seconde. Mais évidemment, le papier est plus rapide.'::text,'arriverait'::text,'arrivera'::text,'arrive'::text,'Si elle envoyait un e-mail, il arriverait en une seconde. Mais évidemment, le papier est plus rapide.'::text),
(384848,42761,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'E-posta gönderse bir saniyede ..., ama tabii ki kâğıt daha hızlı.'::text,'ulaşırdı'::text,'ulaşacak'::text,'ulaşıyor'::text,'E-posta gönderse bir saniyede ulaşırdı, ama tabii ki kâğıt daha hızlı.'::text),
(384849,42761,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha e-mailt küldene, ... egy másodperc alatt. De a papír nyilván gyorsabb.'::text,'megérkezne'::text,'meg fog érkezni'::text,'megérkezik'::text,'Ha e-mailt küldene, megérkezne egy másodperc alatt. De a papír nyilván gyorsabb.'::text),
(384852,42762,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Brief ... in einem cremefarbenen Umschlag verschickt. Wirklich der schnellste Weg, Neuigkeiten zu senden.'::text,'wurde'::text,'verschickte'::text,'verschickte'::text,'Der Brief wurde in einem cremefarbenen Umschlag verschickt. Wirklich der schnellste Weg, Neuigkeiten zu senden.'::text),
(384856,42762,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Лист ... у кремовому конверті. Справді найшвидший спосіб надсилати новини.'::text,'надіслали'::text,'надіслав'::text,'надсилав'::text,'Лист надіслали у кремовому конверті. Справді найшвидший спосіб надсилати новини.'::text),
(384855,42762,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La carta ... en un sobre color crema. Sin duda, la forma más rápida de enviar noticias.'::text,'fue enviada'::text,'envió'::text,'estaba enviando'::text,'La carta fue enviada en un sobre color crema. Sin duda, la forma más rápida de enviar noticias.'::text),
(384854,42762,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La lettre ... dans une enveloppe crème. Vraiment le moyen le plus rapide d''envoyer des nouvelles.'::text,'a été envoyée'::text,'a envoyé'::text,'envoyait'::text,'La lettre a été envoyée dans une enveloppe crème. Vraiment le moyen le plus rapide d''envoyer des nouvelles.'::text),
(384857,42762,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mektup krem rengi bir zarfla ...; haber göndermenin gerçekten en hızlı yolu.'::text,'gönderildi'::text,'gönderdi'::text,'gönderiyordu'::text,'Mektup krem rengi bir zarfla gönderildi; haber göndermenin gerçekten en hızlı yolu.'::text),
(384858,42762,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A levelet ... egy krémszínű borítékban. Tényleg a leggyorsabb módja a hírküldésnek.'::text,'küldték el'::text,'elküldte'::text,'küldte'::text,'A levelet küldték el egy krémszínű borítékban. Tényleg a leggyorsabb módja a hírküldésnek.'::text),
(384861,42763,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... ihren Brief per Post. Bahnbrechende Technologie, ganz klar.'::text,'schickte'::text,'wurde geschickt'::text,'schickend'::text,'Sie schickte ihren Brief per Post. Bahnbrechende Technologie, ganz klar.'::text),
(384865,42763,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... свій лист поштою. Революційна технологія, ясна річ.'::text,'надіслала'::text,'була надіслана'::text,'надсилаючи'::text,'Вона надіслала свій лист поштою. Революційна технологія, ясна річ.'::text),
(384864,42763,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... su carta por correo. Tecnología revolucionaria, está claro.'::text,'envió'::text,'fue enviada'::text,'enviando'::text,'Ella envió su carta por correo. Tecnología revolucionaria, está claro.'::text),
(384863,42763,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... sa lettre par la poste. Une technologie révolutionnaire, clairement.'::text,'a envoyé'::text,'a été envoyée'::text,'envoyant'::text,'Elle a envoyé sa lettre par la poste. Une technologie révolutionnaire, clairement.'::text),
(384866,42763,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mektubunu postayla ...; çığır açan bir teknoloji, belli ki.'::text,'gönderdi'::text,'gönderildi'::text,'göndererek'::text,'Mektubunu postayla gönderdi; çığır açan bir teknoloji, belli ki.'::text),
(384867,42763,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... a levelét postán. Úttörő technológia, nyilván.'::text,'küldte el'::text,'el lett küldve'::text,'küldve'::text,'Ő küldte el a levelét postán. Úttörő technológia, nyilván.'::text),
(384870,42764,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie lächelt, während sie ihn abschickt, also ... dieser Brief kein Rachebrief sein!'::text,'kann'::text,'muss'::text,'sollte'::text,'Sie lächelt, während sie ihn abschickt, also kann dieser Brief kein Rachebrief sein!'::text),
(384874,42764,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона усміхається, коли надсилає його, тож цей лист ... бути листом помсти!'::text,'не може'::text,'мусить'::text,'мав би'::text,'Вона усміхається, коли надсилає його, тож цей лист не може бути листом помсти!'::text),
(384873,42764,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Sonríe mientras la envía, así que esa carta ... ser una carta de venganza!'::text,'no puede'::text,'debe de'::text,'debería'::text,'¡Sonríe mientras la envía, así que esa carta no puede ser una carta de venganza!'::text),
(384872,42764,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle sourit en l''envoyant, donc cette lettre ... être une lettre de vengeance !'::text,'ne peut pas'::text,'doit'::text,'devrait'::text,'Elle sourit en l''envoyant, donc cette lettre ne peut pas être une lettre de vengeance !'::text),
(384875,42764,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gönderirken gülümsüyor, yani o mektup bir intikam mektubu ...!'::text,'olamaz'::text,'olmalı'::text,'olmalı'::text,'Gönderirken gülümsüyor, yani o mektup bir intikam mektubu olamaz!'::text),
(384876,42764,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mosolyog, miközben elküldi, szóval az a levél ... bosszúlevél!'::text,'nem lehet'::text,'biztosan'::text,'kellene hogy legyen'::text,'Mosolyog, miközben elküldi, szóval az a levél nem lehet bosszúlevél!'::text),
(384879,42765,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Brief, ... sie heute abschickt, hat sie den ganzen Vormittag zum Schreiben gekostet.'::text,'den'::text,'wer'::text,'wo'::text,'Der Brief, den sie heute abschickt, hat sie den ganzen Vormittag zum Schreiben gekostet.'::text),
