(384888,42766,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie sagte, sie ... den Brief am nächsten Tag an ihre Oma schicken.'::text,'werde'::text,'wird'::text,'schicke'::text,'Sie sagte, sie werde den Brief am nächsten Tag an ihre Oma schicken.'::text),
(384892,42766,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона сказала, що ... лист бабусі наступного дня.'::text,'надішле'::text,'надішле'::text,'надсилає'::text,'Вона сказала, що надішле лист бабусі наступного дня.'::text),
